  mp3: "audio", wav: "audio", flac: "audio", ogg: "audio",
  pdf: "pdf", zip: "zip", gz: "zip", tar: "zip", rar: "zip", "7z": "zip",
  key: "key", pem: "key", crt: "key", cert: "key",
  txt: "document", rst: "document", log: "document", csv: "document",
