  if (/(?:桌面自动化|自动点击|操作软件|控制(?:应用|软件)|\b(?:automation|ui\s+click)\b)/i.test(value)) required.add("automation");
  const denied = typeof _negatedEffectKindsForTask === "function"
    ? new Set(_negatedEffectKindsForTask(text)) : new Set();
