  const distance = (value) => {
    const meters = number(value);
    if (meters === null) return "";
    if (meters < 1000) return `${Math.round(meters)}m`;
    const km = meters / 1000;
    return `${km >= 10 ? Math.round(km) : km.toFixed(1)}km`;
  };
