        if (vp) vp.innerHTML = `<pre>${_escHtml(list.map((s, i) => `[${i + 1}] ${s}`).join("\n"))}</pre>`;
        return { type: "qr", path: call.path || "", content: list.length ? `二维码内容（识别到 ${list.length} 个）:\n${list.map((s, i) => `[${i + 1}] ${s}`).join("\n")}` : "[ERROR] 没识别到二维码" };
