function openMarketplaceModal() {
  if (_mktModal) { _mktModal.remove(); _mktModal = null; return; }
  const overlay = document.createElement("div");
  overlay.className = "mktm-overlay";
  const modal = document.createElement("div");
  modal.className = "mktm";
  modal.innerHTML = `
    <div class="mktm__head">
      <h2>扩展市场</h2>
      <div class="mktm__search">
        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
        <input type="text" placeholder="搜索扩展…" spellcheck="false" autocomplete="off" />
      </div>
      <button class="mktm__close" type="button"><svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><path d="M4 4l8 8M12 4l-8 8"/></svg></button>
    </div>
    <div class="mktm__filters"></div>
    <div class="mktm__body">
      <div class="mktm__list"></div>
      <div class="mktm__detail" hidden></div>
    </div>
  `;
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  _mktModal = overlay;
  requestAnimationFrame(() => overlay.classList.add("mktm-overlay--visible"));

  let onEsc;
  const closeModal = () => { document.removeEventListener("keydown", onEsc); overlay.classList.remove("mktm-overlay--visible"); setTimeout(() => { overlay.remove(); _mktModal = null; }, 200); };
  onEsc = (e) => { if (e.key === "Escape") closeModal(); };
  overlay.addEventListener("click", (e) => { if (e.target === overlay) closeModal(); });
  modal.querySelector(".mktm__close").addEventListener("click", closeModal);
  document.addEventListener("keydown", onEsc);

  let activeFilter = "all";
  let searchQ = "";
  const FILTERS = [
    { id: "all", label: "全部" }, { id: "featured", label: "推荐" },
    { id: "languages", label: "语言" }, { id: "themes", label: "主题" },
    { id: "tools", label: "工具" }, { id: "ai", label: "AI" },
  ];
  const filtersEl = modal.querySelector(".mktm__filters");
  for (const f of FILTERS) {
    const btn = document.createElement("button");
    btn.className = "mktm__pill" + (f.id === activeFilter ? " is-on" : "");
    btn.textContent = f.label;
    btn.addEventListener("click", () => { activeFilter = f.id; renderList(); });
    filtersEl.appendChild(btn);
  }

  const searchInput = modal.querySelector(".mktm__search input");
  let sTimer = null;
  searchInput.addEventListener("input", () => {
    clearTimeout(sTimer);
    sTimer = setTimeout(() => { searchQ = searchInput.value.trim().toLowerCase(); renderList(); }, 180);
  });
  searchInput.focus();

  const listEl = modal.querySelector(".mktm__list");
  const detailEl = modal.querySelector(".mktm__detail");

  function matchF(e) {
    if (activeFilter === "all") return true;
    if (activeFilter === "featured") return e.featured;
    const cat = (e.category || "").toLowerCase();
    const tags = (e.tags || []).map(t => t.toLowerCase());
    if (activeFilter === "languages") return cat === "languages" || tags.some(t => ["rust","python","language","jupyter"].includes(t));
    if (activeFilter === "themes") return cat === "themes" || tags.some(t => ["theme","icons","ui"].includes(t));
    if (activeFilter === "tools") return ["formatters","linters","web","devops","scm","other"].includes(cat) || tags.some(t => ["formatter","linter","docker","git","server","web","markdown"].includes(t));
    if (activeFilter === "ai") return cat === "ai" || tags.some(t => ["ai","completion"].includes(t));
    return true;
  }

  function filteredList() {
    let list = _mktAllEntries.filter(matchF);
    if (searchQ) list = list.filter(e => e.name.toLowerCase().includes(searchQ) || e.description.toLowerCase().includes(searchQ) || (e.tags||[]).some(t => t.toLowerCase().includes(searchQ)));
    list.sort((a, b) => (b.downloads || 0) - (a.downloads || 0));
    return list;
  }

  function renderList() {
    filtersEl.querySelectorAll(".mktm__pill").forEach((b, i) => b.classList.toggle("is-on", FILTERS[i].id === activeFilter));
    listEl.innerHTML = "";
    detailEl.hidden = true;
    listEl.hidden = false;
    const items = filteredList();
    if (!items.length) {
      listEl.innerHTML = '<div class="mktm__empty"><p>扩展市场暂无内容</p></div>';
      return;
    }
    for (const entry of items) {
      const row = document.createElement("div");
      row.className = "mktm__row";
      row.style.setProperty("--h", _mktHue(entry));
      row.innerHTML = `
        <div class="mktm__icon"><svg viewBox="0 0 24 24" width="28" height="28">${_mktIconFor(entry)}</svg></div>
        <div class="mktm__info">
          <div class="mktm__name">${_escHtml(entry.name)}</div>
          <div class="mktm__desc">${_escHtml(entry.description)}</div>
          <div class="mktm__meta">
            <span class="mktm__author">${_escHtml(entry.author)}</span>
            <span class="mktm__sep">·</span>
            <span>v${entry.version}</span>
            <span class="mktm__sep">·</span>
            <span>${_mktFmtDl(entry.downloads)} 次下载</span>
            <span class="mktm__sep">·</span>
            <span>★ ${(entry.rating || 0).toFixed(1)}</span>
          </div>
        </div>
        <button class="mktm__install-btn" type="button">安装</button>
      `;
      row.querySelector(".mktm__install-btn").addEventListener("click", async (ev) => {
        ev.stopPropagation();
        const btn = ev.target;
        btn.disabled = true; btn.textContent = "安装中…";
        try {
          const msg = await _installExtension(entry);
          btn.textContent = "✓ 已安装"; btn.classList.add("is-done");
          showToast(typeof msg === "string" ? msg : `${entry.name} 已安装`);
        } catch (e) { btn.textContent = "重试"; btn.disabled = false; showToast(String(e?.message || e)); }
      });
      row.addEventListener("click", () => openMktDetail(entry));
      listEl.appendChild(row);
    }
  }

  function openMktDetail(entry) {
    listEl.hidden = true;
    detailEl.hidden = false;
    detailEl.style.setProperty("--h", _mktHue(entry));
    const detailsHtml = (entry.details || "").replace(/^## (.+)$/gm, '<h3 class="mktm__det-h3">$1</h3>').replace(/^- (.+)$/gm, '<div class="mktm__det-li">• $1</div>').replace(/`([^`]+)`/g, '<code>$1</code>').replace(/\n\n/g, '<br/>');
    detailEl.innerHTML = `
      <button class="mktm__back" type="button"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg> 返回</button>
      <div class="mktm__det-head">
        <div class="mktm__det-icon"><svg viewBox="0 0 24 24" width="40" height="40">${_mktIconFor(entry)}</svg></div>
        <div class="mktm__det-info">
          <h2>${_escHtml(entry.name)}</h2>
          <p>${_escHtml(entry.description)}</p>
          <div class="mktm__meta">${_escHtml(entry.author)} · v${entry.version} · ${_mktFmtDl(entry.downloads)} 次下载 · ★ ${(entry.rating||0).toFixed(1)}</div>
        </div>
      </div>
      <div class="mktm__det-tags">${(entry.tags||[]).map(t => `<span class="mktm__tag">${_escHtml(t)}</span>`).join("")}</div>
      <div class="mktm__det-body">${detailsHtml}</div>
      <div class="mktm__det-info-table">
        <table><tbody>
          <tr><td>发布者</td><td>${_escHtml(entry.author)}</td></tr>
          <tr><td>扩展 ID</td><td><code>${_escHtml(entry.id)}</code></td></tr>
          <tr><td>版本</td><td>v${_escHtml(entry.version)}</td></tr>
          <tr><td>分类</td><td>${_escHtml(entry.category || "Other")}</td></tr>
          <tr><td>下载量</td><td>${_mktFmtDl(entry.downloads)}</td></tr>
          <tr><td>评分</td><td>★ ${(entry.rating||0).toFixed(1)}</td></tr>
        </tbody></table>
      </div>
    `;
    detailEl.querySelector(".mktm__back").addEventListener("click", renderList);
    const installBtn = document.createElement("button");
    installBtn.className = "mktm__install-btn mktm__install-btn--lg";
    installBtn.textContent = "安装扩展";
    installBtn.addEventListener("click", async () => {
      installBtn.disabled = true; installBtn.textContent = "安装中…";
      try {
        const msg = await _installExtension(entry);
        installBtn.textContent = "✓ 已安装"; installBtn.classList.add("is-done");
        showToast(typeof msg === "string" ? msg : `${entry.name} 已安装`);
      } catch (e) { installBtn.textContent = "重试"; installBtn.disabled = false; }
    });
    detailEl.querySelector(".mktm__det-head").appendChild(installBtn);
  }

  // 扩展市场已清空——不再展示任何内置 / 远程扩展。
  _mktAllEntries = [];
  renderList();
}

function renderConflictsTool(body) {
  createToolHeader(body, "合并冲突解决", "对照查看 base、我方、对方与合并结果，然后选择采用某一方，或把你手动编辑的结果标记为已解决。");
  const list = document.createElement("div");
  list.className = "tool-list";
  const detail = document.createElement("div");
  detail.className = "merge-detail";
  body.append(list, detail);

  const loadConflicts = async () => {
    list.innerHTML = "";
    detail.innerHTML = "";
    if (!rootPath) {
      list.appendChild(createEmptyState("请先打开一个 Git 工作区。"));
      return;
    }
    let conflicts = [];
    try {
      conflicts = await backend.gitConflicts(rootPath);
    } catch (e) {
      list.appendChild(createEmptyState(String(e && e.message ? e.message : e)));
      return;
    }
    if (!conflicts.length) {
      list.appendChild(createEmptyState("没有发现合并冲突。"));
      return;
    }
    for (const file of conflicts) {
      const row = document.createElement("button");
      row.className = "tool-row";
      row.type = "button";
      row.innerHTML = `${iconImg(fileIconUrl(file.name))}<span></span>`;
      row.querySelector("span").textContent = file.rel;
      row.addEventListener("click", () => openConflictDetail(file, detail));
      list.appendChild(row);
    }
    openConflictDetail(conflicts[0], detail);
  };
  loadConflicts();
}

async function openConflictDetail(file, detail) {
  detail.innerHTML = "";
  let versions;
  try {
    versions = await backend.gitMergeVersions(rootPath, file.rel);
  } catch (e) {
    detail.appendChild(createEmptyState(String(e && e.message ? e.message : e)));
    return;
  }
  const grid = document.createElement("div");
  grid.className = "merge-grid";
  const parts = [
    ["基准", versions.base],
    ["我方", versions.ours],
    ["对方", versions.theirs],
  ];
  for (const [title, text] of parts) {
    const pane = document.createElement("div");
    pane.className = "merge-pane";
    pane.innerHTML = `<strong></strong><pre></pre>`;
    pane.querySelector("strong").textContent = title;
    pane.querySelector("pre").textContent = text || "（空）";
    grid.appendChild(pane);
  }
  const merged = document.createElement("textarea");
  merged.className = "merge-editor";
  merged.spellcheck = false;
  merged.value = versions.merged || "";
  const actions = document.createElement("div");
  actions.className = "tool-actions";
  const resolve = async (resolution) => {
    try {
      if (resolution === "manual") {
        const current = await backend.readTextFile(file.path);
        await _commitDiskTextIfUnchanged(file.path, current, merged.value);
      }
      await backend.gitResolveConflict(rootPath, file.rel, resolution);
      showToast(`已解决 ${file.rel}`);
      await afterWorktreeChange();
      renderFeaturePanel();
    } catch (e) {
      showToast(String(e && e.message ? e.message : e));
    }
  };
  for (const [label, resolution] of [["采用我方", "ours"], ["采用对方", "theirs"], ["标记为手动解决", "manual"]]) {
    const btn = document.createElement("button");
    btn.className = resolution === "manual" ? "btn btn--primary" : "btn";
    btn.type = "button";
    btn.textContent = label;
    btn.addEventListener("click", () => resolve(resolution));
    actions.appendChild(btn);
  }
  detail.append(grid, merged, actions);
}

// Built-in debug configuration templates per adapter. launchArgs carry the
// adapter-specific shape; the active file / workspace fill in the program.
function defaultDebugConfigs() {
  const root = rootPath || "";
  const program = activePath || "";
  return [
    {
      name: "Python：当前文件",
      adapterId: "python",
      request: "launch",
      launchArgs: { type: "python", request: "launch", program, console: "integratedTerminal", cwd: root, stopOnEntry: false },
    },
    {
      name: "Node：当前文件",
      adapterId: "node",
      request: "launch",
      launchArgs: { type: "pwa-node", request: "launch", program, cwd: root, console: "integratedTerminal" },
    },
    {
      name: "Go：调试当前包",
      adapterId: "go",
      request: "launch",
      launchArgs: { type: "go", request: "launch", mode: "debug", program: root, cwd: root },
    },
    {
      name: "LLDB：启动可执行文件",
      adapterId: "lldb",
      request: "launch",
      launchArgs: { type: "lldb", request: "launch", program, cwd: root },
    },
  ];
}

// ---- one-click debug (Debug button / F5 → just run under the debugger, no config screen) ----
// Per-adapter metadata: how to check it's installed and how to install it. Keeps the "just works"
// experience honest — if debugpy/dlv is missing we offer a one-click install instead of hanging on a
// 20s initialize timeout when the spawned adapter exits immediately.
const DAP_ADAPTER_META = {
  python: {
    name: "debugpy",
    check: 'python3 -c "import debugpy" 2>&1',
    // Cascade covers every layout: (1) a project venv (taskRunCapture activates it → plain install
    // lands in the venv); (2) a normal user Python (--user); (3) a Homebrew/PEP-668 "externally
    // managed" python that rejects both (--break-system-packages). `python3 -m pip` guarantees the
    // same interpreter the adapter will run.
    install:
      "python3 -m pip install debugpy 2>/dev/null || python3 -m pip install --user debugpy 2>/dev/null || python3 -m pip install --break-system-packages debugpy",
  },
  go: {
    name: "Delve (dlv)",
    check: "dlv version 2>&1",
    install: "go install github.com/go-delve/delve/cmd/dlv@latest",
  },
  node: {
    name: "vscode-js-debug",
    check: "command -v js-debug-adapter 2>&1",
    install: "npm i -g js-debug-adapter",
  },
  lldb: {
    name: "lldb-dap",
    check: "command -v lldb-dap 2>&1",
    install: "brew install llvm",
  },
};

// Map the active file's language → a zero-config launch config. Mirrors the Run button: detect
// language, then launch. Compiled-native targets (c/cpp/rust) need a prebuilt binary, so they return
// null and fall through to the manual launcher rather than silently mis-launching.
function debugConfigForFile(path) {
  const name = basename(path);
  const ext = name.includes(".") ? name.split(".").pop().toLowerCase() : "";
  const root = rootPath || dirname(path);
  const program = path;
  switch (ext) {
    case "py":
      // internalConsole: debugpy runs the program itself and streams stdout/stderr as output events
      // → our debug console. Avoids the runInTerminal reverse-request (only partially wired), so the
      // debugger reliably attaches and breakpoints hit.
      return { name: "调试当前文件", adapterId: "python", request: "launch", cwd: root,
        launchArgs: { type: "python", request: "launch", program, console: "internalConsole", cwd: root, stopOnEntry: false } };
    case "js": case "mjs": case "cjs":
      return { name: "调试当前文件", adapterId: "node", request: "launch", cwd: root,
        launchArgs: { type: "pwa-node", request: "launch", program, cwd: root, console: "internalConsole" } };
    case "ts": case "tsx":
      return { name: "调试当前文件", adapterId: "node", request: "launch", cwd: root,
        launchArgs: { type: "pwa-node", request: "launch", program, cwd: root, console: "internalConsole",
          runtimeExecutable: "npx", runtimeArgs: ["tsx"] } };
    case "go":
      return { name: "调试当前包", adapterId: "go", request: "launch", cwd: dirname(path),
        launchArgs: { type: "go", request: "launch", mode: "debug", program: dirname(path), cwd: dirname(path) } };
    default:
      return null;
  }
}

// Is the adapter this config needs actually installed? Runs a cheap check through taskRunCapture,
// which uses the same augmented PATH + venv activation as the real adapter spawn, so the answer
// matches what dap_start will see.
async function debugAdapterAvailable(adapterId) {
  const meta = DAP_ADAPTER_META[adapterId];
  if (!meta || !meta.check) return true; // unknown adapter → let the launch attempt surface errors
  const cwd = rootPath || (activePath ? dirname(activePath) : "/tmp");
  try {
    const r = await backend.taskRunCapture(cwd, meta.check);
    return !!r && r.code === 0;
  } catch {
    return false;
  }
}

function offerDebugAdapterInstall(adapterId) {
  const meta = DAP_ADAPTER_META[adapterId];
  if (!meta) return;
  showNotification({
    title: `缺少调试器：${meta.name}`,
    message: `装上它就能像 VS Code 一样打断点、单步执行、查看变量。点一下会自动装好并直接开始调试。`,
    actionLabel: "安装并调试",
    duration: 20000,
    action: () => installDebugAdapterThenStart(adapterId),
  });
}

// Install a debug adapter, then auto-launch the session once it's ready — so a first-time debug is a
// single click even when nothing is installed. Uses the adapter-specific availability check (debugpy
// is a Python *module*, so the generic binary-on-PATH poll in _showInstallProgress can't see it).
async function installDebugAdapterThenStart(adapterId) {
  const meta = DAP_ADAPTER_META[adapterId];
  if (!meta) return;
  await openTerminal();
  writeToActiveTerminal(meta.install + "\n");
  const card = document.createElement("div");
  card.className = "notif-card";
  card.innerHTML = `
    <div class="notif-card__content">
      <div class="notif-card__title">正在安装 ${meta.name}</div>
      <div class="notif-card__msg">${meta.install}</div>
      <div class="notif-progress"><div class="notif-progress__bar"></div></div>
    </div>`;
  _notifContainer.appendChild(card);
  requestAnimationFrame(() => card.classList.add("notif-card--visible"));
  const bar = card.querySelector(".notif-progress__bar");
  let width = 0;
  const tick = setInterval(() => { width = Math.min(width + (90 - width) * 0.05, 95); bar.style.width = width + "%"; }, 300);
  let poll, giveUp, settled = false;
  const finish = (ok, title, msg) => {
    if (settled) return;
    settled = true;
    clearInterval(tick); clearInterval(poll); clearTimeout(giveUp);
    bar.style.width = "100%"; bar.style.background = ok ? "#34c759" : "#ff9f0a";
    card.querySelector(".notif-card__title").textContent = title;
    card.querySelector(".notif-card__msg").textContent = msg;
    setTimeout(() => { card.classList.remove("notif-card--visible"); setTimeout(() => card.remove(), 300); }, ok ? 3500 : 9000);
  };
  poll = setInterval(async () => {
    if (await debugAdapterAvailable(adapterId)) {
      finish(true, `${meta.name} 安装完成`, "正在开始调试…");
      startDebugForActiveFile(); // auto-launch now that the adapter is ready — no second click
    }
  }, 2500);
  // debugpy/dlv/js-debug downloads can run long; keep a generous backstop then let the user retry.
  giveUp = setTimeout(() => finish(false, `${meta.name} 安装较慢`, "在终端看进度；装好后再点一次 Debug 即可"), 300000);
}

// ---- Python: pin the exact interpreter (venv-first) ----
// The backend's augmented PATH prioritizes the project's `.venv/bin`, so a bare `python3` resolves to
// the venv — which typically has the project deps but NOT debugpy → `python3 -m debugpy.adapter` exits
// instantly ("adapter exited", no breakpoints, no output). Meanwhile the pre-flight check runs through
// a login shell and resolves to a DIFFERENT python (e.g. Homebrew) that DOES have debugpy, so it
// passes — a false positive. Fix: resolve the venv interpreter ourselves, pin it as BOTH the adapter
// command and the debuggee `python`, and make sure debugpy lives in THAT interpreter. Bonus: the
// debuggee then runs inside the venv, so the program's own imports (requests, etc.) work.
async function resolveDebugPython() {
  const root = rootPath || (activePath ? dirname(activePath) : "/tmp");
  for (const rel of [".venv/bin/python", "venv/bin/python", ".venv/bin/python3", "venv/bin/python3"]) {
    const p = `${root}/${rel}`;
    try {
      const r = await backend.taskRunCapture(root, `[ -x "${p}" ] && printf %s "${p}"`);
      if (r && r.code === 0 && r.stdout && r.stdout.trim()) return r.stdout.trim();
    } catch { /* keep looking */ }
  }
  // No venv → resolve the login-shell python3's real path so the adapter binary is unambiguous.
  try {
    const r = await backend.taskRunCapture(root, `python3 -c "import sys; print(sys.executable)"`);
    if (r && r.code === 0 && r.stdout && r.stdout.trim()) return r.stdout.trim();
  } catch { /* fall through */ }
  return "python3";
}
async function pythonHasDebugpy(py) {
  const root = rootPath || (activePath ? dirname(activePath) : "/tmp");
  try {
    const r = await backend.taskRunCapture(root, `"${py}" -c "import debugpy" 2>&1`);
    return !!r && r.code === 0;
  } catch { return false; }
}
// Install debugpy INTO the pinned interpreter (e.g. the venv), then auto-start once it imports.
async function installDebugpyThenStart(py) {
  const install = `"${py}" -m pip install debugpy 2>/dev/null || "${py}" -m pip install --user debugpy 2>/dev/null || "${py}" -m pip install --break-system-packages debugpy`;
  await openTerminal();
  writeToActiveTerminal(install + "\n");
  const card = document.createElement("div");
  card.className = "notif-card";
  card.innerHTML = `
    <div class="notif-card__content">
      <div class="notif-card__title">正在为该 Python 安装 debugpy</div>
      <div class="notif-card__msg">${py}</div>
      <div class="notif-progress"><div class="notif-progress__bar"></div></div>
    </div>`;
  _notifContainer.appendChild(card);
  requestAnimationFrame(() => card.classList.add("notif-card--visible"));
  const bar = card.querySelector(".notif-progress__bar");
  let width = 0;
  const tick = setInterval(() => { width = Math.min(width + (90 - width) * 0.05, 95); bar.style.width = width + "%"; }, 300);
  let poll, giveUp, settled = false;
  const finish = (ok, title, msg) => {
    if (settled) return;
    settled = true;
    clearInterval(tick); clearInterval(poll); clearTimeout(giveUp);
    bar.style.width = "100%"; bar.style.background = ok ? "#34c759" : "#ff9f0a";
    card.querySelector(".notif-card__title").textContent = title;
    card.querySelector(".notif-card__msg").textContent = msg;
    setTimeout(() => { card.classList.remove("notif-card--visible"); setTimeout(() => card.remove(), 300); }, ok ? 3500 : 9000);
  };
  poll = setInterval(async () => {
    if (await pythonHasDebugpy(py)) {
      finish(true, "debugpy 安装完成", "正在开始调试…");
      startDebugForActiveFile();
    }
  }, 2500);
  giveUp = setTimeout(() => finish(false, "debugpy 安装较慢", "在终端看进度；装好后再点一次 Debug"), 300000);
}

// The Debug button / F5: one click → run the current file under the debugger. No settings screen —
// this is the VS Code "just press F5" behavior.
async function startDebugForActiveFile() {
  if (dapManager?.isActive()) { enterDebugSidebar(); showDebugDock(); return; } // already debugging → surface it
  if (!activePath) { showToast("先打开一个要调试的文件"); return; }
  const cfg = debugConfigForFile(activePath);
  if (!cfg) {
    // Unsupported language for zero-config debug. Never pop the settings modal — just say so.
    showToast("该文件类型暂不支持一键调试（支持 Python / JS / TS / Go）");
    return;
  }
  showToast(`准备调试 ${basename(activePath)} …`);
  if (cfg.adapterId === "python") {
    // Pin the venv (or login-shell) interpreter for BOTH the adapter and the debuggee, and require
    // debugpy in THAT interpreter — resolving the check-vs-actual python mismatch.
    const py = await resolveDebugPython();
    cfg.command = py;
    cfg.args = ["-m", "debugpy.adapter"];
    cfg.launchArgs.python = py;
    if (!(await pythonHasDebugpy(py))) {
      installDebugpyThenStart(py); // install debugpy into THIS python, then auto-start; no modal
      return;
    }
  } else {
    // Pre-flight the adapter so a missing dlv/js-debug doesn't hang the launch on a 20s init timeout.
    const ok = await debugAdapterAvailable(cfg.adapterId);
    if (!ok) {
      offerDebugAdapterInstall(cfg.adapterId); // notification only → installs then auto-starts; no modal
      return;
    }
  }
  _debugConsoleMounted = false;               // fresh console for this session
  const startPromise = dapManager.start(cfg); // sets `session` synchronously
  enterDebugSidebar();                        // 测试 tab → 调试 (变量/调用栈/断点 on the left)
  showDebugDock();                            // bottom = debug console only
  updateDebugToolbar();                       // floating step controls (also F5/F10/F11/⇧F11/⇧F5)
  try { await startPromise; } catch (e) { showToast("启动调试失败：" + (e?.message || e)); }
  refreshDebugUI();
}

async function loadLaunchConfigs() {
  const configs = [];
  for (const rel of [".vscode/launch.json", ".michael/launch.json"]) {
    if (!rootPath) break;
    try {
      const raw = await backend.readTextFile(`${rootPath}/${rel}`);
      const json = JSON.parse(raw.replace(/\/\/.*$/gm, ""));
      for (const c of json.configurations || []) {
        configs.push({
          name: c.name || `${c.type} ${c.request}`,
          adapterId: dapAdapterForType(c.type),
          request: c.request || "launch",
          launchArgs: c,
        });
      }
    } catch {
      /* no launch.json — fine */
    }
  }
  _launchConfigsCache = configs;
  return configs;
}

function dapAdapterForType(type) {
  const t = String(type || "").toLowerCase();
  if (t.includes("python") || t === "debugpy") return "python";
  if (t.includes("node") || t === "pwa-node" || t.includes("chrome")) return "node";
  if (t === "go") return "go";
  if (t === "lldb" || t === "cppdbg" || t.includes("lldb")) return "lldb";
  return type || "node";
}

let debugConsoleEl = null;

function appendDebugConsole(category, text) {
  if (!debugConsoleEl || !text) return;
  const span = document.createElement("span");
  span.className = "dbg-console__line dbg-console__line--" + (category || "console").replace(/[^a-z]/gi, "");
  span.textContent = text;
  debugConsoleEl.appendChild(span);
  debugConsoleEl.scrollTop = debugConsoleEl.scrollHeight;
}

function refreshDebugUI() {
  updateDebugStatusBar();
  refreshDebugDock();
  if (!featureOverlay.hidden && activeFeatureTab === "debugger") {
    renderFeaturePanel();
  }
}

// ==== Debug UI: left sidebar (变量/调用栈/断点) + bottom console-only dock + floating toolbar ====
// The 测试 tab turns into 调试 while a session runs; the debug console is a tab in the terminal panel
// (peer of the terminal); stepping is keyboard shortcuts (F5/F10/F11/⇧F11/⇧F5) plus a floating toolbar.
let _debugSidebarMode = false;    // the 测试 tab is currently repurposed as 调试
let _debugEnded = false;          // session ended, but we keep the 调试 tab so results stay visible
let _debugConsoleMounted = false; // console shell built for the current session

// -- left sidebar: swap the 测试 tab ⇄ 调试 --
function enterDebugSidebar() {
  _debugSidebarMode = true;
  _debugEnded = false;
  const tab = $("tabTest");
  if (tab) {
    const span = tab.querySelector("span"); if (span) span.textContent = "调试";
    const use = tab.querySelector("use"); if (use) use.setAttribute("href", "#i-bug");
    tab.title = "调试 (⇧⌘T)";
  }
  showSide("debug");
}
// Restore the 测试 tab. Only the caller (a click on 文件/Git/大纲) decides where to navigate — we do
// NOT auto-switch here, so debugging can keep the 调试 tab until the user actively leaves it.
function exitDebugSidebar() {
  _debugSidebarMode = false;
  _debugEnded = false;
  const tab = $("tabTest");
  if (tab) {
    const span = tab.querySelector("span"); if (span) span.textContent = "测试";
    const use = tab.querySelector("use"); if (use) use.setAttribute("href", "#i-beaker");
    tab.title = "测试 (⇧⌘T)";
  }
}

function renderDebugSidebar() {
  const varBody = $("dbgSideVars"), stackBody = $("dbgSideStack"), bpBody = $("dbgSideBps");
  if (!varBody || !stackBody || !bpBody) return;
  const stopped = dapManager?.isStopped();
  const active = dapManager?.isActive();
  // Variables (only meaningful while paused).
  varBody.innerHTML = "";
  if (stopped && dapManager.activeFrameId() != null) {
    loadDebugScopes(varBody, dapManager.activeFrameId());
  } else if (_debugEnded) {
    varBody.appendChild(createEmptyState("调试已结束 · 程序输出见下方控制台"));
  } else {
    varBody.appendChild(createEmptyState(active ? "运行中 — 命中断点后显示" : "未在调试"));
  }
  // Call stack.
  stackBody.innerHTML = "";
  const frames = dapManager?.currentFrames() || [];
  if (!frames.length) {
    stackBody.appendChild(createEmptyState(_debugEnded ? "调试已结束" : (stopped ? "暂无调用栈" : "运行中…")));
  } else {
    for (const f of frames) {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "dbg-frame" + (f.id === dapManager.activeFrameId() ? " is-active" : "");
      row.innerHTML = `<strong></strong><span></span>`;
      row.querySelector("strong").textContent = f.name;
      row.querySelector("span").textContent = f.source?.path ? `${basename(f.source.path)}:${f.line}` : `第 ${f.line} 行`;
      row.addEventListener("click", async () => {
        await dapManager.setActiveFrame(f.id);
        if (f.source?.path) showDebugLocation(f.source.path, f.line);
        renderDebugSidebar();
      });
      stackBody.appendChild(row);
    }
  }
  // Breakpoints (inline — the section already has a 断点 title, so no extra heading).
  bpBody.innerHTML = "";
  const all = getAllBreakpoints();
  if (!all.size) {
    bpBody.appendChild(createEmptyState("点击编辑器行号左侧添加断点"));
  } else {
    for (const [path, lines] of all) {
      for (const line of [...lines].sort((a, b) => a - b)) {
        const row = document.createElement("button");
        row.type = "button";
        row.className = "dbg-bp";
        row.innerHTML = `<span class="dbg-bp__dot"></span><span class="dbg-bp__file"></span>`;
        row.querySelector(".dbg-bp__file").textContent = `${basename(path)}:${line}`;
        row.title = path;
        row.addEventListener("click", () => {
          Promise.resolve(openFile(path, basename(path))).then((ok) => {
            if (ok) { monacoEditor.revealLineInCenter(line); monacoEditor.setPosition({ lineNumber: line, column: 1 }); }
          });
        });
        bpBody.appendChild(row);
      }
    }
  }
}

// -- debug console: a TAB inside the terminal panel (a peer of the terminal, not a separate dock) --
let _dbgConsoleEl = null;        // the console tab's container div, living inside termBody
let _dbgConsoleActive = false;   // the 调试控制台 tab is the currently-shown bottom-panel tab
function ensureDbgConsoleContainer() {
  if (_dbgConsoleEl && _dbgConsoleEl.isConnected) return _dbgConsoleEl;
  if (!termBody) return null;
  _dbgConsoleEl = document.createElement("div");
  _dbgConsoleEl.className = "terminal-panel__instance dbg-console-tab";
  _dbgConsoleEl.hidden = true;
  termBody.appendChild(_dbgConsoleEl);
  return _dbgConsoleEl;
}
function mountDebugConsole() {
  const container = ensureDbgConsoleContainer();
  if (!container) return;
  container.innerHTML = "";
  const consoleEl = document.createElement("div");
  consoleEl.className = "dbg-console dbg-console--tab";
  const inputRow = document.createElement("div");
  inputRow.className = "dbg-console__input";
  inputRow.innerHTML = `<input spellcheck="false" placeholder="输入表达式回车求值…" /><button class="btn" type="button">求值</button>`;
  container.append(consoleEl, inputRow);
  debugConsoleEl = consoleEl;
  for (const entry of (dapManager?.consoleLog() || [])) appendDebugConsole(entry.category, entry.text);
  const evalInput = inputRow.querySelector("input");
  const doEval = async () => {
    const expr = evalInput.value.trim(); if (!expr) return;
    appendDebugConsole("input", `> ${expr}\n`); evalInput.value = "";
    const res = await dapManager.evaluate(expr, dapManager.activeFrameId(), "repl");
    appendDebugConsole("result", `${res?.result ?? "（无结果）"}\n`);
  };
  inputRow.querySelector("button").addEventListener("click", doEval);
  evalInput.addEventListener("keydown", (e) => { if (e.key === "Enter") doEval(); });
  _debugConsoleMounted = true;
}

// -- floating toolbar (top-center of the editor) --
let _dbgFloat = null;
const _DBG_ICONS = {
  continue: `<svg viewBox="0 0 16 16"><path d="M4 3l9 5-9 5z"/></svg>`,
  pause: `<svg viewBox="0 0 16 16"><path d="M6 3v10M10 3v10"/></svg>`,
  stepOver: `<svg viewBox="0 0 16 16"><path d="M3 8a5 5 0 0 1 9-3"/><path d="M12 2v3.5H8.5"/><circle cx="8" cy="12" r="1.4" fill="currentColor" stroke="none"/></svg>`,
  stepIn: `<svg viewBox="0 0 16 16"><path d="M8 2v6.5"/><path d="M5.2 6l2.8 2.8L10.8 6"/><circle cx="8" cy="12.6" r="1.4" fill="currentColor" stroke="none"/></svg>`,
  stepOut: `<svg viewBox="0 0 16 16"><path d="M8 8.5V2"/><path d="M5.2 4.5L8 1.7l2.8 2.8"/><circle cx="8" cy="12.6" r="1.4" fill="currentColor" stroke="none"/></svg>`,
  restart: `<svg viewBox="0 0 16 16"><path d="M13 8a5 5 0 1 1-1.6-3.7"/><path d="M13 2v3h-3"/></svg>`,
  stop: `<svg viewBox="0 0 16 16"><rect x="4" y="4" width="8" height="8" rx="1.2" fill="currentColor" stroke="none"/></svg>`,
};
function ensureDebugToolbar() {
  if (_dbgFloat) return _dbgFloat;
  // Anchor to the editor area (below the file tabs), not the whole editorwrap, so it doesn't cover tabs.
  const wrap = $("editorContainer") || document.querySelector(".editorwrap");
  if (!wrap) return null;
  _dbgFloat = document.createElement("div");
  _dbgFloat.className = "dbg-float";
  _dbgFloat.hidden = true;
  const btn = (act, cls, title, icon) => `<button class="dbg-float__btn ${cls}" data-act="${act}" title="${title}" aria-label="${title}">${icon}</button>`;
  _dbgFloat.innerHTML =
    btn("continue", "dbg-float__btn--go", "继续 (F5)", _DBG_ICONS.continue) +
    btn("pause", "", "暂停", _DBG_ICONS.pause) +
    btn("stepOver", "", "单步跳过 (F10)", _DBG_ICONS.stepOver) +
    btn("stepIn", "", "单步进入 (F11)", _DBG_ICONS.stepIn) +
    btn("stepOut", "", "单步跳出 (⇧F11)", _DBG_ICONS.stepOut) +
    `<span class="dbg-float__sep"></span>` +
    btn("restart", "", "重启", _DBG_ICONS.restart) +
    btn("stop", "dbg-float__btn--stop", "停止 (⇧F5)", _DBG_ICONS.stop);
  _dbgFloat.addEventListener("click", (e) => {
    const act = e.target.closest("[data-act]")?.dataset.act; if (!act) return;
    ({ continue: () => dapManager.cont(), pause: () => dapManager.pause(), stepOver: () => dapManager.next(),
       stepIn: () => dapManager.stepIn(), stepOut: () => dapManager.stepOut(), restart: () => dapManager.restart(),
       stop: () => dapManager.stop() })[act]?.();
  });
  wrap.appendChild(_dbgFloat);
  return _dbgFloat;
}
function updateDebugToolbar() {
  const bar = ensureDebugToolbar(); if (!bar) return;
  const active = dapManager?.isActive();
  bar.hidden = !active;
  if (!active) return;
  const stopped = dapManager.isStopped();
  const dis = (act, off) => { const b = bar.querySelector(`[data-act="${act}"]`); if (b) b.disabled = off; };
  dis("continue", !stopped); dis("pause", stopped);
  dis("stepOver", !stopped); dis("stepIn", !stopped); dis("stepOut", !stopped);
}

// -- orchestration: the debug console is a tab in the terminal panel (same level as the terminal) --
function showDebugDock() {
  if (!termPanel) return;
  ensureDbgConsoleContainer();
  if (!_debugConsoleMounted) mountDebugConsole();
  termPanel.hidden = false;                          // open the shared bottom panel
  editorwrapEl?.classList.add("has-terminal");
  for (const t of termTabs) if (t.container) t.container.hidden = true; // hide terminals…
  if (_dbgConsoleEl) _dbgConsoleEl.hidden = false;   // …show the debug console
  _dbgConsoleActive = true;
  renderTermTabs();
  try { monacoEditor.layout(); } catch {}
}
// Close the 调试控制台 tab (its X, or a stop). If terminals remain, show one; else close the panel.
function hideDebugDock() {
  if (_dbgConsoleEl) { _dbgConsoleEl.remove(); _dbgConsoleEl = null; }
  _dbgConsoleActive = false;
  _debugConsoleMounted = false;
  debugConsoleEl = null;
  if (termTabs.length > 0) {
    activeTermTab = Math.max(0, Math.min(activeTermTab, termTabs.length - 1));
    if (termTabs[activeTermTab]?.container) termTabs[activeTermTab].container.hidden = false;
    renderTermTabs();
    requestAnimationFrame(() => { try { termTabs[activeTermTab].fit.fit(); termTabs[activeTermTab].term.focus(); } catch {} });
  } else {
    try { closeTerminal(); } catch {}
    renderTermTabs();
  }
}
// Refresh the live views on every state change: sidebar (vars/stack/bps) + floating toolbar. The
// console is append-only (mounted once), so it is NOT re-rendered here (that would wipe output).
function refreshDebugDock() {
  if (_debugSidebarMode && !$("viewDebug")?.hidden) renderDebugSidebar();
  updateDebugToolbar();
}
function markDebugDockEnded() {
  if (debugConsoleEl) appendDebugConsole("console", "\n── 程序已退出 ──\n");
  _debugEnded = true;
  updateDebugToolbar();          // hides the floating bar (session no longer active)
  // Do NOT revert the 调试 tab or close the console here — keep the output visible so the user can
  // read results. The 调试 sidebar flips back to 测试 only on a 文件/Git/大纲 click; the console tab
  // closes only via its own X.
  if (_debugSidebarMode) renderDebugSidebar();
}

function renderDebuggerTool(body) {
  createToolHeader(
    body,
    "调试器",
    "一个真正的 Debug Adapter Protocol 客户端：在编辑器侧边栏设置断点，启动一个配置，然后逐步执行代码，实时查看调用栈、变量和调试控制台。需要安装匹配的适配器（debugpy、vscode-js-debug/node、delve、lldb-dap）。",
  );

  const active = dapManager?.isActive();
  debugConsoleEl = null;

  if (_launchConfigsCache === null && rootPath) {
    _launchConfigsCache = [];
    loadLaunchConfigs().then(() => refreshDebugUI());
  }

  if (!active) {
    renderDebugLauncher(body);
    return;
  }
  renderDebugSession(body);
}

function renderDebugLauncher(body) {
  const form = document.createElement("div");
  form.className = "tool-form";
  const configs = [...defaultDebugConfigs(), ...(_launchConfigsCache || [])];
  const optionsHtml = configs.map((c, i) => `<option value="${i}">${c.name}</option>`).join("");
  form.innerHTML = `
    <label><span>配置</span><select id="dapConfig">${optionsHtml}</select></label>
    <details class="dbg-advanced"><summary>高级（自定义适配器命令）</summary>
      <label><span>适配器 id</span><input id="dapAdapter" spellcheck="false" placeholder="python / node / go / lldb" /></label>
      <label><span>自定义命令</span><input id="dapCommand" spellcheck="false" placeholder="留空则使用内置默认值" /></label>
      <label><span>参数</span><input id="dapArgs" spellcheck="false" placeholder="以空格分隔" /></label>
      <label><span>工作目录</span><input id="dapCwd" spellcheck="false" /></label>
    </details>
    <div class="tool-actions">
      <button class="btn btn--primary" id="dapStartBtn" type="button">开始调试</button>
      <button class="btn" id="dapReloadBtn" type="button">重新加载 launch.json</button>
    </div>`;
  body.appendChild(form);
  form.querySelector("#dapCwd").value = rootPath || "";

  renderBreakpointsSection(body);

  form.querySelector("#dapStartBtn").addEventListener("click", async () => {
    const idx = +form.querySelector("#dapConfig").value;
    const base = configs[idx] ? structuredCloneSafe(configs[idx]) : null;
    const customCmd = form.querySelector("#dapCommand").value.trim();
    const customAdapter = form.querySelector("#dapAdapter").value.trim();
    const cwd = form.querySelector("#dapCwd").value.trim() || rootPath || null;
    let config = base || { name: customAdapter || "Custom", adapterId: customAdapter || "node", request: "launch", launchArgs: {} };
    if (customAdapter) config.adapterId = customAdapter;
    if (customCmd) {
      config.command = customCmd;
      config.args = form.querySelector("#dapArgs").value.trim().split(/\s+/).filter(Boolean);
    }
    config.cwd = cwd;
    if (config.launchArgs) {
      config.launchArgs.cwd = config.launchArgs.cwd || cwd;
      if (!config.launchArgs.program && activePath) config.launchArgs.program = activePath;
    }
    await dapManager.start(config);
  });
  form.querySelector("#dapReloadBtn").addEventListener("click", async () => {
    await loadLaunchConfigs();
    refreshDebugUI();
    showToast("已重新加载启动配置");
  });
}

function structuredCloneSafe(obj) {
  try { return structuredClone(obj); } catch { return JSON.parse(JSON.stringify(obj)); }
}

function renderDebugSession(body) {
  // Toolbar.
  const bar = document.createElement("div");
  bar.className = "dbg-toolbar";
  const stopped = dapManager.isStopped();
  const mk = (label, title, fn, disabled) =>
    `<button class="btn dbg-ctl" data-act="${label}" title="${title}" ${disabled ? "disabled" : ""}>${title}</button>`;
  bar.innerHTML =
    mk("continue", stopped ? "继续" : "运行中…", null, !stopped) +
    mk("stepOver", "单步跳过", null, !stopped) +
    mk("stepIn", "单步进入", null, !stopped) +
    mk("stepOut", "单步跳出", null, !stopped) +
    mk("pause", "暂停", null, stopped) +
    mk("restart", "重启", null, false) +
    mk("stop", "停止", null, false);
  body.appendChild(bar);
  bar.addEventListener("click", (e) => {
    const act = e.target.closest("[data-act]")?.dataset.act;
    if (!act) return;
    const map = {
      continue: () => dapManager.cont(),
      stepOver: () => dapManager.next(),
      stepIn: () => dapManager.stepIn(),
      stepOut: () => dapManager.stepOut(),
      pause: () => dapManager.pause(),
      restart: () => dapManager.restart(),
      stop: () => dapManager.stop(),
    };
    map[act]?.();
  });

  const grid = document.createElement("div");
  grid.className = "dbg-grid";
  body.appendChild(grid);

  // Call stack.
  const stackCol = document.createElement("div");
  stackCol.className = "dbg-col";
  stackCol.innerHTML = `<h4 class="dbg-h">调用栈</h4>`;
  const stackList = document.createElement("div");
  stackList.className = "dbg-stack";
  stackCol.appendChild(stackList);
  const frames = dapManager.currentFrames();
  if (!frames.length) {
    stackList.appendChild(createEmptyState(stopped ? "暂无调用栈。" : "运行中 — 暂停或命中断点后即可查看。"));
  } else {
    for (const f of frames) {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "dbg-frame" + (f.id === dapManager.activeFrameId() ? " is-active" : "");
      row.innerHTML = `<strong></strong><span></span>`;
      row.querySelector("strong").textContent = f.name;
      row.querySelector("span").textContent = f.source?.path
        ? `${basename(f.source.path)}:${f.line}`
        : `第 ${f.line} 行`;
      row.addEventListener("click", async () => {
        await dapManager.setActiveFrame(f.id);
        if (f.source?.path) showDebugLocation(f.source.path, f.line);
      });
      stackList.appendChild(row);
    }
  }
  grid.appendChild(stackCol);

  // Variables.
  const varCol = document.createElement("div");
  varCol.className = "dbg-col";
  varCol.innerHTML = `<h4 class="dbg-h">变量</h4>`;
  const varTree = document.createElement("div");
  varTree.className = "dbg-vars";
  varCol.appendChild(varTree);
  grid.appendChild(varCol);
  if (stopped && dapManager.activeFrameId() != null) {
    loadDebugScopes(varTree, dapManager.activeFrameId());
  } else {
    varTree.appendChild(createEmptyState("暂停时才会显示变量。"));
  }

  // Breakpoints.
  renderBreakpointsSection(body);

  // Debug Console.
  const consoleWrap = document.createElement("div");
  consoleWrap.className = "dbg-console-wrap";
  consoleWrap.innerHTML = `<h4 class="dbg-h">调试控制台</h4>`;
  const consoleEl = document.createElement("div");
  consoleEl.className = "dbg-console";
  const inputRow = document.createElement("div");
  inputRow.className = "dbg-console__input";
  inputRow.innerHTML = `<input spellcheck="false" placeholder="求值表达式…" /><button class="btn" type="button">求值</button>`;
  consoleWrap.append(consoleEl, inputRow);
  body.appendChild(consoleWrap);
  debugConsoleEl = consoleEl;
  for (const entry of dapManager.consoleLog()) appendDebugConsole(entry.category, entry.text);

  const evalInput = inputRow.querySelector("input");
  const doEval = async () => {
    const expr = evalInput.value.trim();
    if (!expr) return;
    appendDebugConsole("input", `> ${expr}\n`);
    evalInput.value = "";
    const res = await dapManager.evaluate(expr, dapManager.activeFrameId(), "repl");
    appendDebugConsole("result", `${res?.result ?? "（无结果）"}\n`);
  };
  inputRow.querySelector("button").addEventListener("click", doEval);
  evalInput.addEventListener("keydown", (e) => { if (e.key === "Enter") doEval(); });
}

async function loadDebugScopes(container, frameId) {
  container.innerHTML = "";
  const scopes = await dapManager.scopes(frameId);
  if (!scopes.length) {
    container.appendChild(createEmptyState("暂无作用域。"));
    return;
  }
  for (const scope of scopes) {
    const node = document.createElement("details");
    node.className = "dbg-scope";
    node.open = !scope.expensive;
    node.innerHTML = `<summary>${scope.name}</summary>`;
    const inner = document.createElement("div");
    inner.className = "dbg-var-children";
    node.appendChild(inner);
    container.appendChild(node);
    let loaded = false;
    const load = async () => {
      if (loaded) return;
      loaded = true;
      await renderVariables(inner, scope.variablesReference);
    };
    if (node.open) load();
    node.addEventListener("toggle", () => { if (node.open) load(); });
  }
}

async function renderVariables(container, variablesReference) {
  if (!variablesReference) return;
  const vars = await dapManager.variables(variablesReference);
  for (const v of vars) {
    const hasChildren = v.variablesReference && v.variablesReference > 0;
    const row = document.createElement(hasChildren ? "details" : "div");
    row.className = "dbg-var";
    if (hasChildren) {
      row.innerHTML = `<summary><span class="dbg-var__name"></span><span class="dbg-var__val"></span></summary>`;
      const kids = document.createElement("div");
      kids.className = "dbg-var-children";
      row.appendChild(kids);
      let loaded = false;
      row.addEventListener("toggle", async () => {
        if (row.open && !loaded) { loaded = true; await renderVariables(kids, v.variablesReference); }
      });
    } else {
      row.innerHTML = `<span class="dbg-var__name"></span><span class="dbg-var__val"></span>`;
    }
    row.querySelector(".dbg-var__name").textContent = v.name;
    row.querySelector(".dbg-var__val").textContent = v.value;
    container.appendChild(row);
  }
}

function renderBreakpointsSection(body) {
  const col = document.createElement("div");
  col.className = "dbg-col dbg-breakpoints";
  col.innerHTML = `<h4 class="dbg-h">断点</h4>`;
  const list = document.createElement("div");
  list.className = "dbg-bp-list";
  col.appendChild(list);
  body.appendChild(col);
  const all = getAllBreakpoints();
  if (!all.size) {
    list.appendChild(createEmptyState("点击编辑器侧边栏即可添加断点。"));
    return;
  }
  for (const [path, lines] of all) {
    for (const line of lines.sort((a, b) => a - b)) {
      const row = document.createElement("button");
      row.type = "button";
      row.className = "dbg-bp";
      row.innerHTML = `<span class="dbg-bp__dot"></span><span class="dbg-bp__file"></span>`;
      row.querySelector(".dbg-bp__file").textContent = `${basename(path)}:${line}`;
      row.title = path;
      row.addEventListener("click", () => {
        Promise.resolve(openFile(path, basename(path))).then((ok) => {
          if (ok) { monacoEditor.revealLineInCenter(line); monacoEditor.setPosition({ lineNumber: line, column: 1 }); }
        });
      });
      list.appendChild(row);
    }
  }
}

// Hoisted so renderLspTool can drop the prior render's "lsp-log" listener before re-adding —
// the feature panel re-renders on every tab click, so this would otherwise stack on `document`.
let _lspLogHandler = null;
function renderLspTool(body) {
  createToolHeader(
    body,
    "语言服务",
    "真正的 LSP 智能能力 — 自动补全、诊断、悬停提示、跳转到定义、查找引用、重命名、符号与代码操作。打开匹配的文件时，Rust、Python、Go 和 C/C++ 的服务器会自动启动；TS/JS/JSON/CSS/HTML 仍由 Monaco 内置服务提供支持。",
  );
  const form = document.createElement("div");
  form.className = "tool-form";
  form.innerHTML = `
    <label><span>语言</span><select id="lspLang"><option>rust</option><option>python</option><option>go</option><option>c</option><option>cpp</option><option>typescript</option><option>javascript</option><option>html</option><option>css</option><option>json</option></select></label>
    <label><span>自定义命令</span><input id="lspCommand" spellcheck="false" placeholder="留空则使用内置默认服务器" /></label>
    <label><span>参数</span><input id="lspArgs" spellcheck="false" placeholder="以空格分隔" /></label>
    <div class="tool-actions"><button class="btn btn--primary" id="lspStartBtn" type="button">启动</button><button class="btn" id="lspStopBtn" type="button">停止</button><button class="btn" id="lspRefreshBtn" type="button">刷新</button></div>
    <div class="tool-list" id="lspList"></div>
    <pre class="tool-log" id="lspLog"></pre>`;
  body.appendChild(form);
  const log = form.querySelector("#lspLog");
  const langSel = form.querySelector("#lspLang");

  const refresh = () => {
    const list = form.querySelector("#lspList");
    list.innerHTML = "";
    const status = lspManager ? lspManager.status() : [];
    const running = new Map(status.map((s) => [s.lang, s]));
    const known = ["rust", "python", "go", "c", "cpp", "typescript", "javascript", "html", "css", "json"];
    for (const lang of known) {
      const s = running.get(lang);
      const managed = lspManager?.managedLangs.includes(lang);
      const row = document.createElement("div");
      row.className = "tool-card";
      row.innerHTML = `<div class="tool-card__main"><strong></strong><span></span></div><span class="lsp-dot"></span>`;
      row.querySelector("strong").textContent = lang;
      let state;
      if (s && s.initialized) state = "运行中 · 已初始化";
      else if (s) state = "启动中…";
      else if (managed) state = "打开时自动启动";
      else state = "Monaco 内置";
      row.querySelector("span").textContent = state;
      const dot = row.querySelector(".lsp-dot");
      dot.style.cssText = `width:8px;height:8px;border-radius:50%;margin-left:auto;background:${s && s.initialized ? "#3fb950" : s ? "#d29922" : "#6e7681"}`;
      list.appendChild(row);
    }
  };

  const renderLog = () => {
    const lang = langSel.value;
    log.textContent = (lspLogBuffers.get(lang) || []).join("\n");
    log.scrollTop = log.scrollHeight;
  };
  // Drop the previous render's handler first (feature panel re-renders on every tab click) so this
  // document-level listener doesn't stack, each closing over a now-detached langSel/log.
  if (_lspLogHandler) document.removeEventListener("lsp-log", _lspLogHandler);
  _lspLogHandler = (e) => { if (e.detail?.lang === langSel.value) renderLog(); };
  document.addEventListener("lsp-log", _lspLogHandler);
  langSel.addEventListener("change", renderLog);

  form.querySelector("#lspStartBtn").addEventListener("click", async () => {
    const lang = langSel.value;
    const command = form.querySelector("#lspCommand").value.trim();
    const args = form.querySelector("#lspArgs").value.trim().split(/\s+/).filter(Boolean);
    try {
      const client = await lspManager.startManual(lang, command ? { command, args } : undefined);
      if (client) showToast(`LSP ${lang} 已启动`);
      refresh();
      renderLog();
    } catch (e) {
      showToast(String(e && e.message ? e.message : e));
    }
  });
  form.querySelector("#lspStopBtn").addEventListener("click", async () => {
    const lang = langSel.value;
    try {
      await lspManager.stop(lang);
      showToast(`LSP ${lang} 已停止`);
      refresh();
    } catch (e) {
      showToast(String(e && e.message ? e.message : e));
    }
  });
  form.querySelector("#lspRefreshBtn").addEventListener("click", refresh);
  refresh();
  renderLog();
}

