// Session picker (/sessions): browse every conversation in this workspace — name,
// project, mode, message count, last-message preview — and jump into one to continue.
function _openSessionPicker() {
  const overlay = document.createElement("div");
  overlay.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.45);display:flex;align-items:center;justify-content:center;z-index:99999";
  const modal = document.createElement("div");
  modal.style.cssText = "width:min(680px,94vw);max-height:80vh;display:flex;flex-direction:column;background:var(--panel,#fff);border:1px solid var(--border,rgba(128,128,128,.3));border-radius:14px;box-shadow:0 20px 60px rgba(0,0,0,.5);overflow:hidden";
  modal.innerHTML =
    `<div style="display:flex;align-items:center;gap:8px;padding:12px 16px;border-bottom:1px solid var(--border,rgba(128,128,128,.2))">` +
      `<span style="font-size:14px;font-weight:600">会话记忆</span>` +
      `<span class="sp-count" style="font-size:12px;opacity:.55"></span>` +
      `<button class="sp-close" type="button" style="margin-left:auto;background:none;border:none;color:inherit;cursor:pointer;font-size:16px;opacity:.6">✕</button>` +
    `</div>` +
    `<input class="sp-search" type="text" placeholder="搜索会话内容…" style="margin:10px 14px 4px;padding:8px 10px;font:13px system-ui;background:var(--bg,#f8f9fa);color:inherit;border:1px solid var(--border,rgba(128,128,128,.3));border-radius:8px;outline:none">` +
    `<div class="sp-list" style="overflow:auto;padding:6px 8px 12px"></div>`;
  overlay.appendChild(modal);
  document.body.appendChild(overlay);
  const close = () => overlay.remove();
  modal.querySelector(".sp-close").addEventListener("click", close);
  overlay.addEventListener("click", (e) => { if (e.target === overlay) close(); });
  const listEl = modal.querySelector(".sp-list");
  const searchEl = modal.querySelector(".sp-search");
  modal.querySelector(".sp-count").textContent = `${_chatSessions.length} 个`;

  const render = (q) => {
    q = (q || "").trim().toLowerCase();
    listEl.innerHTML = "";
    const rows = _chatSessions.map((s, i) => ({ s, i })).filter(({ s }) => {
      if (!q) return true;
      const hay = (s.name + " " + (s.project || "") + " " + (s.memory ? s.memory.assemble() : (s.history || [])).map((m) => m.content || "").join(" ")).toLowerCase();
      return hay.includes(q);
    });
    if (!rows.length) { listEl.innerHTML = `<div style="padding:20px;text-align:center;opacity:.5;font-size:13px">没有匹配的会话</div>`; return; }
    for (const { s, i } of rows) {
      const last = s.memory.recent.length ? String(s.memory.recent[s.memory.recent.length - 1].content || "") : "";
      const preview = last.replace(/\s+/g, " ").slice(0, 90) || "(空会话)";
      const proj = s.project ? (s.project.split("/").filter(Boolean).pop() || "") : "";
      const modeObj = _AI_MODES.find((m) => m.id === s.mode);
      const active = i === _activeChatIdx;
      const row = document.createElement("button");
      row.type = "button";
      row.style.cssText = `display:block;width:100%;text-align:left;padding:9px 11px;margin:3px 0;border:1px solid ${active ? "var(--accent,#1a73e8)" : "transparent"};border-radius:9px;background:${active ? "color-mix(in srgb,var(--accent,#1a73e8) 8%,transparent)" : "transparent"};color:inherit;cursor:pointer`;
      row.innerHTML =
        `<div style="display:flex;align-items:center;gap:7px;font-size:13px;font-weight:600">` +
          `<span class="sp-dot" style="width:7px;height:7px;border-radius:50%;flex:0 0 auto;background:${modeObj?.color || "#888"}"></span>` +
          `<span class="sp-name"></span>` +
          (proj ? `<span class="sp-proj" style="font-size:11px;font-weight:400;opacity:.6;padding:1px 6px;border-radius:6px;background:var(--hover,rgba(128,128,128,.14))"></span>` : "") +
          `<span style="margin-left:auto;font-size:11px;font-weight:400;opacity:.5">${s.memory ? s.memory.recent.length : (s.history || []).length} 条 · ${modeObj?.label || s.mode}${active ? " · 当前" : ""}</span>` +
        `</div>` +
        `<div class="sp-prev" style="font-size:12px;opacity:.62;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap"></div>`;
      row.querySelector(".sp-name").textContent = s.name;
      if (proj) row.querySelector(".sp-proj").textContent = proj;
      row.querySelector(".sp-prev").textContent = preview;
      row.addEventListener("mouseenter", () => { if (!active) row.style.background = "var(--hover,rgba(128,128,128,.1))"; });
      row.addEventListener("mouseleave", () => { if (!active) row.style.background = "transparent"; });
      row.addEventListener("click", () => { _switchChatSession(i); close(); promptEl.focus(); });
      listEl.appendChild(row);
    }
  };
  render("");
  searchEl.addEventListener("input", () => render(searchEl.value));
  setTimeout(() => searchEl.focus(), 30);
}
let _slashMatches = [];
let _slashActive = -1;
const _slashMenu = document.createElement("div");
_slashMenu.className = "atmenu";
_slashMenu.hidden = true;
document.body.appendChild(_slashMenu);
function _hideSlash() { _slashMenu.hidden = true; _slashActive = -1; _slashMatches = []; }
function _renderSlashActive() { [..._slashMenu.children].forEach((c, i) => c.classList.toggle("is-active", i === _slashActive)); }
function _updateSlashMenu() {
  const m = /^\/(\w*)$/.exec(promptEl.value);
  if (!m) return _hideSlash();
  const q = m[1].toLowerCase();
  _slashMatches = _SLASH.filter((s) => s.cmd.startsWith(q));
  if (!_slashMatches.length) return _hideSlash();
  _slashMenu.innerHTML = "";
  _slashMatches.forEach((s, i) => {
    const item = document.createElement("div");
    item.className = "atmenu__item" + (i === 0 ? " is-active" : "");
    item.innerHTML = `<b>/${_escHtml(s.cmd)}</b> <span style="opacity:.6;margin-left:6px">${_escHtml(s.desc)}</span>`;
    item.addEventListener("mousedown", (e) => { e.preventDefault(); _pickSlash(i); });
    _slashMenu.appendChild(item);
  });
  _slashActive = 0;
  const r = promptEl.getBoundingClientRect();
  _slashMenu.style.left = r.left + "px";
  _slashMenu.style.width = Math.min(r.width, 520) + "px";
  _slashMenu.style.bottom = window.innerHeight - r.top + 6 + "px";
  _slashMenu.hidden = false;
}
function _pickSlash(i) {
  const s = _slashMatches[i];
  if (!s) return _hideSlash();
  _hideSlash();
  // Action commands (e.g. /sessions) run a UI action instead of filling a prompt.
  if (typeof s.action === "function") { promptEl.value = ""; promptEl.style.height = "auto"; try { s.action(); } catch (e) { console.warn("[slash]", e); } return; }
  promptEl.value = s.prompt;
  promptEl.style.height = "auto";
  promptEl.style.height = Math.min(promptEl.scrollHeight, 160) + "px";
  promptEl.focus();
}
promptEl.addEventListener("keydown", (e) => {
  if (_slashMenu.hidden) return;
  if (e.key === "ArrowDown") { e.preventDefault(); _slashActive = Math.min(_slashActive + 1, _slashMatches.length - 1); _renderSlashActive(); }
  else if (e.key === "ArrowUp") { e.preventDefault(); _slashActive = Math.max(_slashActive - 1, 0); _renderSlashActive(); }
  else if (e.key === "Enter" || e.key === "Tab") { e.preventDefault(); e.stopPropagation(); _pickSlash(_slashActive); }
  else if (e.key === "Escape") { e.preventDefault(); _hideSlash(); }
});
promptEl.addEventListener("blur", () => setTimeout(_hideSlash, 150));

let _pastedImages = [];

function _createImagePreview(attachment, idx) {
  const wrap = document.createElement("div");
  wrap.className = "prompt-image-preview";
  const src = attachment.dataUrl || attachment.objectUrl || (attachment.path ? (inTauri ? backend.assetUrl(attachment.path) : attachment.path) : attachment.frames?.[0] || "");
  if (attachment.kind === "video") {
    const video = document.createElement("video");
    video.src = src;
    video.muted = true;
    video.preload = "metadata";
    video.playsInline = true;
    video._mediaAttachment = attachment;
    wrap.appendChild(video);
    const badge = document.createElement("span");
    badge.className = "prompt-image-preview__video-badge";
    badge.textContent = "VIDEO";
    wrap.appendChild(badge);
  } else {
    const image = document.createElement("img");
    image.src = src;
    image.alt = attachment.name || "Pasted image";
    wrap.appendChild(image);
  }
  const remove = document.createElement("button");
  remove.className = "prompt-image-preview__remove";
  remove.type = "button";
  remove.title = "Remove";
  remove.innerHTML = "&times;";
  wrap.appendChild(remove);
  wrap.querySelector("button").addEventListener("click", () => {
    _releaseAttachmentObjectUrl(_pastedImages[idx]);
    _pastedImages = _pastedImages.filter((_, i) => i !== idx);
    _refreshImagePreviews();
  });
  return wrap;
}

function _replaceVideoWithKeyFrame(video, attachment) {
  const frame = Array.isArray(attachment?.frames)
    ? attachment.frames.find((value) => typeof value === "string" && value.startsWith("data:image/"))
    : "";
  if (!frame || !video?.parentNode) return false;
  const image = document.createElement("img");
  image.src = frame;
  image.className = video.classList?.contains("msg__attached-video") ? "msg__attached-image" : (video.className || "");
  image.alt = attachment.name || "Video key frame";
  image.title = "视频关键帧";
  image.addEventListener("click", () => showImageLightbox(image.src));
  video.replaceWith(image);
  return true;
}

let _mediaAttachmentSeq = 0;
function _ensureAttachmentId(attachment) {
  if (!attachment || typeof attachment !== "object") return "";
  const existing = String(attachment.id || "").trim();
  if (existing) return existing;
  let generated = "";
  try { generated = globalThis.crypto?.randomUUID?.() || ""; } catch {}
  if (!generated) generated = `media-${Date.now().toString(36)}-${(++_mediaAttachmentSeq).toString(36)}`;
  attachment.id = generated;
  return generated;
}

function _bindVideoAttachmentFallback(video, attachment) {
  if (!video || !attachment) return;
  video._mediaAttachment = attachment;
  const attachmentId = _ensureAttachmentId(attachment);
  if (attachmentId && video.dataset) video.dataset.mediaAttachmentId = attachmentId;
  video.addEventListener("error", async () => {
    if (attachment.path && inTauri) {
      try {
        const dataUrl = await backend.readFileDataUrl(attachment.path);
        if (typeof dataUrl === "string" && dataUrl.startsWith("data:video/")) {
          video.addEventListener("error", () => _replaceVideoWithKeyFrame(video, attachment), { once: true });
          video.src = dataUrl;
          return;
        }
      } catch {}
    }
    _replaceVideoWithKeyFrame(video, attachment);
  }, { once: true });
}

function _rehydrateSnapshotVideoFallbacks(session) {
  const videos = Array.from(session?.container?.querySelectorAll?.("video.msg__attached-video") || []);
  if (!videos.length) return;
  const messages = session?.memory?.assemble?.() || [];
  const attachmentsById = new Map(messages
    .flatMap((message) => Array.isArray(message?.attachments) ? message.attachments : [])
    .filter((attachment) => attachment?.kind === "video" && attachment.id)
    .map((attachment) => [String(attachment.id), attachment]));
  // Never infer by DOM order: conversation compaction can remove an old
  // attachment from memory while its rendered node remains in the rich HTML.
  for (const video of videos) {
    const attachmentId = String(video.dataset?.mediaAttachmentId || "");
    const attachment = attachmentId ? attachmentsById.get(attachmentId) : null;
    if (attachment) _bindVideoAttachmentFallback(video, attachment);
  }
}

function _releaseAttachmentObjectUrl(attachment, scope = null, replaceWithFrame = false) {
  if (!attachment?.objectUrl || !String(attachment.objectUrl).startsWith("blob:")) return;
  const objectUrl = String(attachment.objectUrl);
  if (scope?.querySelectorAll) {
    for (const video of scope.querySelectorAll("video")) {
      const src = video.getAttribute("src") || video.src || "";
      if (src !== objectUrl) continue;
      try { video.pause(); } catch {}
      if (!replaceWithFrame || !_replaceVideoWithKeyFrame(video, attachment)) {
        try { video.removeAttribute("src"); video.load(); } catch {}
      }
    }
  }
  try { URL.revokeObjectURL(objectUrl); } catch {}
  attachment.objectUrl = "";
}

function _releaseMessagesAttachmentUrls(messages, scope = null, replaceWithFrame = false) {
  for (const message of Array.isArray(messages) ? messages : []) {
    for (const attachment of Array.isArray(message?.attachments) ? message.attachments : []) {
      _releaseAttachmentObjectUrl(attachment, scope, replaceWithFrame);
    }
  }
}

function _releaseBlobMediaInNode(node) {
  if (!node?.querySelectorAll) return;
  const released = new Set();
  for (const video of node.querySelectorAll("video")) {
    const attachment = video._mediaAttachment;
    const src = video.getAttribute("src") || video.src || "";
    if (attachment?.objectUrl) {
      released.add(String(attachment.objectUrl));
      _releaseAttachmentObjectUrl(attachment);
    }
    if (String(src).startsWith("blob:") && !released.has(String(src))) {
      try { URL.revokeObjectURL(String(src)); } catch {}
    }
    try { video.pause(); video.removeAttribute("src"); video.load(); } catch {}
  }
}

function _refreshImagePreviews() {
  let container = document.querySelector(".prompt-images");
  if (!container) {
    container = document.createElement("div");
    container.className = "prompt-images";
    promptEl.parentElement.insertBefore(container, promptEl);
  }
  container.innerHTML = "";
  _pastedImages.forEach((attachment, i) => container.appendChild(_createImagePreview(attachment, i)));
  if (_pastedImages.length === 0) container.remove();
}

function _validEmbeddedCoordinate(value, min, max) {
  return Number.isFinite(value) && value >= min && value <= max ? value : null;
}

// Read only location-related EXIF fields from the original Blob. This must run
// before Canvas resizing, which commonly strips metadata from the model image.
async function _extractEmbeddedImageLocation(blob) {
  try {
    const gps = await exifr.gps(blob);
    const latitude = _validEmbeddedCoordinate(gps?.latitude, -90, 90);
    const longitude = _validEmbeddedCoordinate(gps?.longitude, -180, 180);
    if (latitude === null || longitude === null) {
      return {
        status: "embedded_location_absent",
        coordinateSource: null,
        metadataAuthenticity: "not_verified",
      };
    }
    const tags = await exifr.parse(blob, ["GPSHPositioningError"]).catch(() => null);
    const rawAccuracy = tags?.GPSHPositioningError;
    const reportedAccuracyM = Number.isFinite(rawAccuracy) && rawAccuracy >= 0 ? rawAccuracy : null;
    return {
      status: "embedded_gps",
      latitude,
      longitude,
      reportedAccuracyM,
      coordinateSource: "embedded_exif_gps",
      metadataAuthenticity: "not_verified",
      reverseGeocoding: [],
      sourceStatuses: [],
      retrievedAt: null,
      limitations: [
        "EXIF GPS is metadata stored in the image file; it can be edited, copied, or stale and is not an authenticity proof.",
        reportedAccuracyM === null
          ? "The image does not report GPS horizontal positioning error, so coordinate accuracy is unknown."
          : "reportedAccuracyM is the image metadata's GPSHPositioningError value, not an independently measured accuracy.",
      ],
    };
  } catch {
    return {
      status: "embedded_location_unreadable",
      coordinateSource: null,
      metadataAuthenticity: "not_verified",
      limitations: ["The IDE could not parse location metadata from the attachment bytes it received; this does not prove that the source file never contained GPS metadata."],
    };
  }
}

function _isImageLocationRequest(text, hasImageContext = false) {
  if (!hasImageContext) return false;
  const value = String(text || "").toLowerCase();
  const developerContext = /\b(cdn|url|uri|src|href|css|html|object-fit|position|absolute|relative|fixed)\b|样式|布局|页面|代码|文件路径|资源地址|图片地址|链接地址|元素位置|定位属性/i.test(value);
  const explicitGeography = /拍摄|拍的|拍于|经纬度|\bgps\b|\bexif\b|街区|街道|城市|国家|地理位置|geo[- ]?locat|where.{0,20}(taken|shot)|neighbou?rhood|coordinates?/i.test(value);
  if (developerContext && !explicitGeography) return false;
  return /(?:这张|这个|这幅|这是|它|照片|图片|图).{0,14}(?:在哪|哪里|哪儿|什么地方|哪个(?:街区|街道|城市|国家)|拍摄地|拍摄位置|在哪里拍|哪儿拍)|(?:在哪|哪里|哪儿|什么地方|哪个街区).{0,14}(?:拍|照片|图片|这张|这个|它)|(?:定位|地理定位).{0,10}(?:照片|图片|这张|这个|它)|what\s+neighbou?rhood\s+is\s+(?:this|it)|where.{0,20}(?:photo|image|picture|this|it).{0,20}(?:taken|shot|located)|(?:photo|image|picture).{0,16}(?:location|neighbou?rhood|where)/i.test(value);
}

async function _ensureAttachmentLocationEvidence(attachment) {
  const evidence = attachment?.locationEvidence;
  if (!evidence || evidence.status === "embedded_location_absent"
    || !Number.isFinite(evidence.latitude) || !Number.isFinite(evidence.longitude)) return evidence || null;
  if (Array.isArray(evidence.reverseGeocoding) && evidence.reverseGeocoding.length) return evidence;
  if (!inTauri || typeof backend?.reverseGeocodeCoordinates !== "function") return evidence;
  if (attachment._locationEvidencePromise) return attachment._locationEvidencePromise;
  attachment._locationEvidencePromise = (async () => {
    try {
      const response = await backend.reverseGeocodeCoordinates(evidence.latitude, evidence.longitude, document.documentElement.lang || "zh");
      evidence.reverseGeocoding = Array.isArray(response?.candidates) ? response.candidates.slice(0, 4) : [];
      evidence.sourceStatuses = Array.isArray(response?.source_statuses) ? response.source_statuses.slice(0, 4) : [];
      evidence.retrievedAt = Number.isFinite(response?.retrieved_at) ? response.retrieved_at : null;
      evidence.limitations = [
        ...(Array.isArray(evidence.limitations) ? evidence.limitations : []),
        ...(Array.isArray(response?.limitations) ? response.limitations : []),
      ].slice(0, 10);
      evidence.status = evidence.reverseGeocoding.length ? "embedded_gps_resolved" : "embedded_gps_unresolved";
    } catch (error) {
      evidence.status = "embedded_gps_reverse_failed";
      evidence.sourceStatuses = [{ source: "reverse_geocoding", status: "failed", detail: String(error?.message || error).slice(0, 360) }];
    }
    return evidence;
  })().finally(() => { delete attachment._locationEvidencePromise; });
  return attachment._locationEvidencePromise;
}

function _attachmentLocationEvidenceContext(attachment) {
  const evidence = attachment?.locationEvidence;
  if (attachment?.mediaSourceChanged || evidence?.invalidatedReason === "source_file_changed") {
    return "图片定位证据不可用：会话保存的文件路径现在指向不同内容，旧画面与旧 EXIF/地图反查证据已全部停用，未把新文件冒充原附件。";
  }
  if (evidence?.invalidatedReason === "missing_source_fingerprint") {
    return "图片定位证据不可用：这是旧版本保存的路径附件，没有原始内容指纹，无法证明当前文件仍是原图；旧 EXIF/地图反查证据已停用。";
  }
  if (evidence?.status === "embedded_location_unreadable") {
    return [
      "图片定位证据：IDE 无法解析它收到的附件字节中的位置元数据；这不证明相机原片从未包含 GPS，剪贴板、截图或转发过程可能已重编码。",
      "继续执行视觉定位流程，但不得声称已检查并确认原始相机文件没有 GPS。",
    ].join("\n");
  }
  if (!evidence || evidence.status === "embedded_location_absent") {
    return [
      "图片定位证据：IDE 收到的附件字节中没有可读取的嵌入式 GPS 坐标；这不等于原始相机文件一定没有 GPS，剪贴板、截图或转发过程可能已剥离元数据。",
      "不要在这里提前停止。先逐项记录可观察的文字、楼体年代与密度、阳台/窗型、道路与交通设施、地貌、天际线、植被气候和拍摄视角；把观察与推断分开。",
      "若画面仍有区分度，给出最多三个按可能性排序的城市或区域视觉候选，并逐个写支持点、反证点和低/中/高定性置信；这些必须明确标成未核验推断，不能编造百分比。若确实没有区分度，再明确说明无法缩小到城市或街区。",
      "只有清晰路牌、门牌、店名、公交/地铁站名或独特地标才适合继续搜索并调用真实地理来源核验到街道/街区；没有可检索线索时不要用泛化搜索结果假装核验。不得把截图、广告或翻拍内容中的地址当成拍摄位置。",
    ].join("\n");
  }
  const structured = JSON.stringify({
    status: evidence.status,
    coordinates: {
      latitude: evidence.latitude,
      longitude: evidence.longitude,
      source: evidence.coordinateSource,
      reported_accuracy_m: evidence.reportedAccuracyM ?? null,
    },
    metadata_authenticity: evidence.metadataAuthenticity,
    reverse_geocoding_candidates: evidence.reverseGeocoding || [],
    source_statuses: evidence.sourceStatuses || [],
    retrieved_at: evidence.retrievedAt ?? null,
    limitations: evidence.limitations || [],
  }, null, 2);
  return [
    "图片定位证据（从缩放前的原始图片本地提取）：",
    structured,
    "表达约束：坐标只能称为图片 EXIF 元数据报告的位置，EXIF 可被修改；地图反查标签是公开数据库中的附近候选。来源门牌或标签冲突时必须逐项报告，不得合并成确定地址；retrieved_at 不是照片拍摄时间或地图更新时间。",
  ].join("\n");
}

// Downscale a pasted/dropped image so vision models actually get a clean, in-budget
// image. Frontier models internally resize to ~1.15MP anyway, and a raw 4K screenshot
// (5-10MB base64) trips the payload cap and gets stripped ("读不懂图片"). Cap the long
// edge at 1568px (Claude's text-optimal tile) → keep PNG when it stays small (crisp text),
// else JPEG. Small images pass through untouched (best fidelity). Never throws.
function _downscaleImageForVision(dataUrl, maxDim = 1568, stripMetadata = false) {
  return new Promise((resolve) => {
    const decodeFallback = () => resolve(stripMetadata ? "" : dataUrl);
    try {
      const img = new Image();
      img.onload = () => {
        try {
          const w = img.naturalWidth || img.width, h = img.naturalHeight || img.height;
          const long = Math.max(w, h);
          if (!long) return decodeFallback();
          // Already small enough → keep original bytes.
          const needsRaster = String(dataUrl).startsWith("data:image/svg+xml");
          if (!stripMetadata && !needsRaster && long <= maxDim && String(dataUrl).length < 1_300_000) return resolve(dataUrl);
          const scale = long > maxDim ? maxDim / long : 1;
          const cw = Math.max(1, Math.round(w * scale)), ch = Math.max(1, Math.round(h * scale));
          const cv = document.createElement("canvas");
          cv.width = cw; cv.height = ch;
          const cx = cv.getContext("2d");
          cx.imageSmoothingEnabled = true; cx.imageSmoothingQuality = "high";
          cx.drawImage(img, 0, 0, cw, ch);
          let out = cv.toDataURL("image/png");
          if (out.length > 1_500_000) out = cv.toDataURL("image/jpeg", 0.9); // bound big/photographic
          resolve(stripMetadata ? (out || "") : (out && out.length < String(dataUrl).length ? out : dataUrl));
        } catch { decodeFallback(); }
      };
      img.onerror = decodeFallback;
      img.src = dataUrl;
    } catch { decodeFallback(); }
  });
}

function _readFileAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(reader.error || new Error("媒体读取失败"));
    reader.readAsDataURL(file);
  });
}

// Sample a few real video frames for vision APIs, which generally accept images
// but not arbitrary video_url blocks. The original video remains playable in UI.
async function _extractVideoFrames(dataUrl, maxFrames = 3) {
  const video = document.createElement("video");
  video.muted = true;
  video.preload = "auto";
  video.playsInline = true;
  const waitEvent = (name, timeout = 10000) => new Promise((resolve, reject) => {
    const timer = setTimeout(() => { cleanup(); reject(new Error(`video ${name} timeout`)); }, timeout);
    const done = () => { cleanup(); resolve(); };
    const failed = () => { cleanup(); reject(new Error("video decode failed")); };
    const cleanup = () => { clearTimeout(timer); video.removeEventListener(name, done); video.removeEventListener("error", failed); };
    video.addEventListener(name, done, { once: true });
    video.addEventListener("error", failed, { once: true });
  });
  try {
    video.src = dataUrl;
    await waitEvent("loadeddata");
    const duration = Number.isFinite(video.duration) && video.duration > 0 ? video.duration : 0;
    const times = duration > 0.2
      ? [0, duration * 0.5, Math.max(0, duration * 0.9)].slice(0, maxFrames)
      : [0];
    const frames = [];
    for (const time of times) {
      if (time > 0.01) {
        video.currentTime = Math.min(time, Math.max(0, duration - 0.01));
        await waitEvent("seeked", 7000);
      }
      const width = video.videoWidth || 0, height = video.videoHeight || 0;
      if (!width || !height) continue;
      const scale = Math.min(1, 1280 / Math.max(width, height));
      const canvas = document.createElement("canvas");
      canvas.width = Math.max(1, Math.round(width * scale));
      canvas.height = Math.max(1, Math.round(height * scale));
      const context = canvas.getContext("2d");
      context.drawImage(video, 0, 0, canvas.width, canvas.height);
      frames.push(canvas.toDataURL("image/jpeg", 0.82));
    }
    return frames;
  } catch {
    return [];
  } finally {
    try { video.pause(); video.removeAttribute("src"); video.load(); } catch {}
  }
}

async function _mediaAttachmentFromFile(file) {
  const name = String(file?.name || "");
  const declaredMime = String(file?.type || "").toLowerCase();
  const inferredMime = _mediaMimeForName(name);
  const kind = declaredMime.startsWith("video/") || isVideoFile(name)
    ? "video"
    : declaredMime.startsWith("image/") || isImageFile(name) ? "image" : "";
  if (!kind) throw new Error("媒体格式无法识别");
  const usableDeclaredMime = declaredMime && declaredMime !== "application/octet-stream" ? declaredMime : "";
  if (usableDeclaredMime && !usableDeclaredMime.startsWith(kind + "/")) throw new Error("媒体格式与文件扩展名不一致");
  const mime = usableDeclaredMime || inferredMime;
  if (!mime.startsWith(kind + "/")) throw new Error("媒体格式无法识别");
  if (kind === "image" && Number(file?.size || 0) > 25 * 1024 * 1024) throw new Error("图片超过 25 MB，请先压缩后再发送");
  if (kind === "video" && Number(file?.size || 0) > 40 * 1024 * 1024) throw new Error("视频超过 40 MB，请先压缩或截取关键片段");
  const readable = usableDeclaredMime ? file : new Blob([file], { type: mime });
  if (kind === "image") {
    const [original, locationEvidence] = await Promise.all([
      _readFileAsDataUrl(readable),
      _extractEmbeddedImageLocation(readable),
    ]);
    const dataUrl = await _downscaleImageForVision(original, 1568, true);
    return { kind, mime, name: name || "image.png", path: file.path || "", dataUrl, modelMediaSanitized: !!dataUrl, sourceFingerprint: await _mediaSourceFingerprint(original), frames: [], locationEvidence };
  }
  const objectUrl = URL.createObjectURL(readable);
  const frames = await _extractVideoFrames(objectUrl);
  if (file.path) { try { URL.revokeObjectURL(objectUrl); } catch {} }
  return { kind, mime, name: name || "video.mp4", path: file.path || "", dataUrl: "", objectUrl: file.path ? "" : objectUrl, frames };
}

function _mediaMimeForName(name) {
  const ext = (String(name || "").split(".").pop() || "").toLowerCase();
  return ({
    png: "image/png", jpg: "image/jpeg", jpeg: "image/jpeg", gif: "image/gif", webp: "image/webp",
    svg: "image/svg+xml", ico: "image/x-icon", bmp: "image/bmp", avif: "image/avif",
    mp4: "video/mp4", webm: "video/webm", ogv: "video/ogg", ogg: "video/ogg",
    mov: "video/quicktime", m4v: "video/x-m4v",
  })[ext] || "";
}

async function _mediaAttachmentFromPath(path) {
  const normalizedPath = _toPosix(path);
  const name = basename(normalizedPath);
  const kind = isVideoFile(name) ? "video" : "image";
  // Read only the exact file the user dropped. Registering its parent as a
  // workspace would silently grant the agent access to every sibling file.
  const source = backend.assetUrl(normalizedPath);
  const response = await fetch(source);
  if (!response.ok) throw new Error(`${kind === "video" ? "视频" : "图片"}读取失败`);
  const maxBytes = (kind === "video" ? 40 : 25) * 1024 * 1024;
  const announcedBytes = Number(response.headers?.get?.("content-length")) || 0;
  if (announcedBytes > maxBytes) throw new Error(`${kind === "video" ? "视频超过 40 MB，请先压缩或截取关键片段" : "图片超过 25 MB，请先压缩后再发送"}`);
  const blob = await response.blob();
  if (blob.size > maxBytes) throw new Error(`${kind === "video" ? "视频超过 40 MB，请先压缩或截取关键片段" : "图片超过 25 MB，请先压缩后再发送"}`);
  const inferredMime = _mediaMimeForName(name);
  const responseMime = String(blob.type || "").toLowerCase();
  if (responseMime && responseMime !== "application/octet-stream" && !responseMime.startsWith(kind + "/")) throw new Error(`${kind === "video" ? "视频" : "图片"}格式无法识别`);
  const mime = responseMime && responseMime !== "application/octet-stream" ? responseMime : inferredMime;
  if (!mime.startsWith(kind + "/")) throw new Error(`${kind === "video" ? "视频" : "图片"}格式无法识别`);
  if (kind === "image") {
    const [original, locationEvidence] = await Promise.all([
      _readFileAsDataUrl(blob),
      _extractEmbeddedImageLocation(blob),
    ]);
    const dataUrl = await _downscaleImageForVision(original, 1568, true);
    return { kind, mime, name, path: normalizedPath, dataUrl, modelMediaSanitized: !!dataUrl, sourceFingerprint: await _mediaSourceFingerprint(original), frames: [], locationEvidence };
  }
  const objectUrl = URL.createObjectURL(blob);
  let frames;
  try { frames = await _extractVideoFrames(objectUrl); }
  finally { try { URL.revokeObjectURL(objectUrl); } catch {} }
  return { kind, mime, name, path: normalizedPath, dataUrl: "", objectUrl: "", frames };
}

promptEl.addEventListener("paste", (e) => {
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (/^(image|video)\//.test(item.type)) {
      e.preventDefault();
      const file = item.getAsFile();
      if (!file) continue;
      _mediaAttachmentFromFile(file).then((attachment) => {
          _pastedImages.push(attachment);
          _refreshImagePreviews();
          showToast(attachment.kind === "video" ? "Video attached" : "Image attached");
        }).catch((error) => showToast(String(error?.message || error)));
      return;
    }
  }
});

promptEl.parentElement.addEventListener("dragover", (e) => { e.preventDefault(); e.dataTransfer.dropEffect = "copy"; });
promptEl.parentElement.addEventListener("drop", async (e) => {
  e.preventDefault();
  const files = e.dataTransfer?.files;
  const items = e.dataTransfer?.items;
  
  // Handle directory drop (Electron only)
  if (items) {
    for (const item of items) {
      if (item.kind === 'file') {
        const entry = item.webkitGetAsEntry?.();
        if (entry?.isDirectory) {
          const relativePath = await window.__TAURI__?.path.relative(rootPath, entry.fullPath);
          const ref = `@${relativePath || entry.name}/`;
          promptEl.value += (promptEl.value ? "\n" : "") + ref;
          promptEl.dispatchEvent(new Event("input"));
          showToast(`目录引用已插入: ${ref}`);
          continue;
        }
      }
    }
  }
  
  if (!files) return;
  for (const file of files) {
    const isMedia = /^(image|video)\//.test(file.type) || isImageFile(file.name) || isVideoFile(file.name);
    if (isMedia) {
      try {
        const attachment = await _mediaAttachmentFromFile(file);
        _pastedImages.push(attachment);
        _refreshImagePreviews();
        showToast(`${attachment.kind === "video" ? "Video" : "Image"} attached: ${file.name}`);
      } catch (error) { showToast(String(error?.message || error)); }
      continue;
    }
    // Check if it's a file path reference (from Finder/Explorer)
    if (file.path) {
      const relativePath = await window.__TAURI__?.path.relative(rootPath, file.path);
      const ref = `@${relativePath || file.name}`;
      promptEl.value += (promptEl.value ? "\n" : "") + ref;
      promptEl.dispatchEvent(new Event("input"));
      showToast(`文件引用已插入: ${ref}`);
      continue;
    }
    
    if (file.size < 100000) {
      const reader = new FileReader();
      reader.onload = () => {
        const text = reader.result;
        promptEl.value += (promptEl.value ? "\n\n" : "") + `[File: ${file.name}]\n${text}`;
        promptEl.dispatchEvent(new Event("input"));
        showToast(`File attached: ${file.name}`);
      };
      reader.readAsText(file);
    } else {
      showToast(`File too large: ${file.name} (${(file.size / 1024).toFixed(0)} KB)`);
    }
  }
});

// ---- quick open (⌘P) ----
const quickOpenOverlay = document.createElement("div");
quickOpenOverlay.className = "palette";
quickOpenOverlay.hidden = true;
quickOpenOverlay.innerHTML = `
  <div class="palette__panel" role="dialog" aria-label="Quick open">
    <input class="palette__input" type="text" placeholder="" spellcheck="false" />
    <div class="palette__list" role="listbox"></div>
  </div>`;
document.body.appendChild(quickOpenOverlay);

const qoInput = quickOpenOverlay.querySelector(".palette__input");
const qoList = quickOpenOverlay.querySelector(".palette__list");
let qoFiles = [];
let qoFiltered = [];
let qoCursor = 0;

async function collectProjectFiles() {
  if (!rootPath) return [];
  const result = [];
  const skip = new Set(["node_modules", ".git", "dist", "build", "out", "target", ".next", "coverage", ".cache", "vendor"]);
  const stack = [rootPath];
  const prefix = rootPath.endsWith("/") ? rootPath : rootPath + "/";
  while (stack.length && result.length < 5000) {
    const dir = stack.pop();
    let entries;
    try { entries = await backend.readDir(dir); } catch { continue; }
    for (const e of entries) {
      if (e.is_dir) {
        if (!skip.has(e.name)) stack.push(e.path);
      } else {
        const rel = e.path.startsWith(prefix) ? e.path.slice(prefix.length) : e.name;
        result.push({ path: e.path, name: e.name, rel });
      }
    }
  }
  return result;
}

function qoFuzzyMatch(str, query) {
  const lower = str.toLowerCase();
  const q = query.toLowerCase();
  let qi = 0, score = 0, lastMatch = -1;
  for (let i = 0; i < lower.length && qi < q.length; i++) {
    if (lower[i] === q[qi]) {
      score += (lastMatch === i - 1) ? 10 : 1;
      if (i === 0 || str[i - 1] === "/" || str[i - 1] === "." || str[i - 1] === "-" || str[i - 1] === "_")
        score += 5;
      lastMatch = i;
      qi++;
    }
  }
  return qi === q.length ? score : -1;
}

function qoRefresh() {
  const q = qoInput.value.trim();
  if (!q) {
    qoFiltered = qoFiles.slice(0, 50);
  } else {
    qoFiltered = qoFiles
      .map((f) => ({ f, s: qoFuzzyMatch(f.rel, q) }))
      .filter((x) => x.s > 0)
      .sort((a, b) => b.s - a.s)
      .slice(0, 50)
      .map((x) => x.f);
  }
  qoCursor = 0;
  qoRender();
}

function qoRender() {
  qoList.innerHTML = "";
  if (!qoFiltered.length) {
    const empty = document.createElement("div");
    empty.className = "palette__empty";
    empty.textContent = t("quickOpen.noResults");
    qoList.appendChild(empty);
    return;
  }
  qoFiltered.forEach((file, i) => {
    const row = document.createElement("div");
    row.className = "palette__item" + (i === qoCursor ? " is-active" : "");
    row.setAttribute("role", "option");
    row.innerHTML = `${iconImg(fileIconUrl(file.name))}<span class="palette__title"></span><span class="palette__cat"></span>`;
    row.querySelector(".palette__title").textContent = file.name;
    const dir = file.rel.includes("/") ? file.rel.slice(0, file.rel.lastIndexOf("/")) : "";
    if (dir) row.querySelector(".palette__cat").textContent = dir;
    row.addEventListener("mousemove", () => { if (qoCursor !== i) { qoCursor = i; qoRender(); } });
    row.addEventListener("click", () => qoSelect(file));
    qoList.appendChild(row);
  });
  const active = qoList.querySelector(".is-active");
  if (active) active.scrollIntoView({ block: "nearest" });
}

function qoSelect(file) {
  qoClose();
  openFile(file.path, file.name);
}

async function qoOpen() {
  qoInput.value = "";
  qoInput.placeholder = t("quickOpen.placeholder");
  quickOpenOverlay.hidden = false;
  qoFiles = await collectProjectFiles();
  qoRefresh();
  qoInput.focus();
}

function qoClose() {
  quickOpenOverlay.hidden = true;
}

qoInput.addEventListener("input", qoRefresh);
qoInput.addEventListener("keydown", (e) => {
  if (e.key === "ArrowDown") { e.preventDefault(); qoCursor = Math.min(qoCursor + 1, qoFiltered.length - 1); qoRender(); }
  else if (e.key === "ArrowUp") { e.preventDefault(); qoCursor = Math.max(qoCursor - 1, 0); qoRender(); }
  else if (e.key === "Enter") { e.preventDefault(); if (qoFiltered[qoCursor]) qoSelect(qoFiltered[qoCursor]); }
  else if (e.key === "Escape") { e.preventDefault(); qoClose(); }
});
quickOpenOverlay.addEventListener("mousedown", (e) => { if (e.target === quickOpenOverlay) qoClose(); });

// ---- terminal → IDE sync ----
let _termRefreshTimer = null;
const _TERM_REFRESH_PATTERNS = [
  /Successfully installed/i,
  /pip install/i,
  /npm install/i,
  /pnpm install/i,
  /yarn add/i,
  /cargo build/i,
  /go get/i,
  /gem install/i,
  /luarocks install/i,
  /composer require/i,
  // NOTE: deliberately no "shell prompt" pattern — `/\$\s*$/` matched almost any
  // output containing `$`, so it fired a full reloadDir + git + LSP refresh on
  // nearly every terminal chunk while the agent ran commands (a periodic freeze).
  // We only refresh after recognizably state-changing commands (installs/builds).
];

let _termOutputBuf = "";
let _termScanPending = false;
function _detectTerminalChanges(data) {
  // Accumulate cheaply on EVERY chunk, but only run the (multi-regex) scan on a
  // throttle — running it per chunk was a real cause of UI lag while a terminal
  // floods output (e.g. a dev server / npm install). At most ~3 scans/sec now.
  _termOutputBuf += data;
  if (_termOutputBuf.length > 4000) _termOutputBuf = _termOutputBuf.slice(-2000);
  if (_termScanPending) return;
  _termScanPending = true;
  setTimeout(() => {
    _termScanPending = false;
    for (const re of _TERM_REFRESH_PATTERNS) {
      if (re.test(_termOutputBuf)) { _scheduleTermRefresh(); _termOutputBuf = ""; return; }
    }
  }, 300);
}

function _scheduleTermRefresh() {
  if (_termRefreshTimer) clearTimeout(_termRefreshTimer);
  _termRefreshTimer = setTimeout(() => {
    if (rootPath) {
      reloadDir(rootPath);
      refreshGitStatus();
    }

    const model = monacoEditor.getModel();
    if (model) {
      const langId = model.getLanguageId();
      _envSymbolsLoaded = false;
      _envLoadingLang = null;
      _loadEnvSymbols(langId);
    }
  }, 5000);
}

