// ---- recent projects ----
async function addRecentProject(path) {
  if (!inTauri || !path) return;
  try {
    const store = await loadStore("session.json");
    let list = (await store.get(RECENT_PROJECTS_KEY)) || [];
    list = list.filter((p) => p !== path);
    list.unshift(path);
    if (list.length > MAX_RECENT) list.length = MAX_RECENT;
    await store.set(RECENT_PROJECTS_KEY, list);
    await store.save();
    renderRecentProjects(list);
  } catch (e) {
    console.warn("[recent] save failed:", e);
  }
}

async function loadRecentProjects() {
  if (!inTauri) return;
  try {
    const store = await loadStore("session.json");
    const list = (await store.get(RECENT_PROJECTS_KEY)) || [];
    renderRecentProjects(list);
  } catch { /* ignore */ }
}

function renderRecentProjects(list) {
  const container = $("welcomeRecent");
  const ul = $("recentList");
  if (!container || !ul) return;
  // Keep only real string paths — a legacy/corrupt recent list could hold null entries
  // that crash on render ("t.split is not a function").
  list = (Array.isArray(list) ? list : []).filter((p) => typeof p === "string" && p);
  if (!list.length) { container.hidden = true; return; }
  container.hidden = false;
  ul.innerHTML = "";
  for (const path of list.slice(0, 4)) {
    const li = document.createElement("li");
    const name = basename(path);
    li.innerHTML = `<span class="recent-name"></span><span class="recent-path"></span>`;
    li.querySelector(".recent-name").textContent = name;
    li.querySelector(".recent-path").textContent = path;
    li.addEventListener("click", () => openFolder(path));
    ul.appendChild(li);
  }
}

loadRecentProjects();

// ---- session persistence ----
const SESSION_STORE_KEY = "michael-ide.session";

// Quota-aware localStorage write: on a QuotaExceededError, evict large non-critical
// keys (recordings / episodes / caches) and retry once; if still failing, warn the user
// ONCE instead of silently losing data. Returns whether the write landed.
let _lsQuotaWarned = false;
function _lsSafeSet(key, val) {
  try { localStorage.setItem(key, val); return true; }
  catch (e) {
    try {
      for (const k of Object.keys(localStorage)) {
        if (k === key) continue;
        if (/recording|episode|workflow|web-cache|-cache|backup-old|demo-rec/i.test(k)) localStorage.removeItem(k);
      }
      localStorage.setItem(key, val);
      return true;
    } catch (e2) {
      if (!_lsQuotaWarned) { _lsQuotaWarned = true; try { showToast("⚠ 浏览器本地存储已满，部分历史/草稿可能存不下——建议清理或导出聊天记录"); } catch {} }
      return false;
    }
  }
}
// SYNCHRONOUS hot-exit backup of UNSAVED editor buffers. The 800ms autosave debounce
// + async-only close saves meant edits typed in the last moment (or on crash / HMR /
// force-quit / the dev watcher killing the process) were silently lost. localStorage
// writes are synchronous, so this always lands; restoreSession re-applies it.
function _flushDirtyBuffersSync() {
  try {
    const dirty = [];
    for (const [path, f] of openFiles) {
      if (f && f.dirty && f.model && !f.isImage && !f.isVideo) {
        try { dirty.push({ path, content: f.model.getValue() }); } catch {}
      }
    }
    if (dirty.length) _lsSafeSet("michael-ide.unsaved-buffers", JSON.stringify(dirty));
    else localStorage.removeItem("michael-ide.unsaved-buffers");
  } catch { /* quota / disabled */ }
}

// SYNCHRONOUS mirror of the session blob (open tabs / workspace / active file) so a
// non-clean exit (which only fires beforeunload, where the async store.save can't
// finish) still restores the workspace. restoreSession falls back to this.
function _flushSessionSync() {
  if (_isSecondaryWindow) return; // don't clobber the main window's mirror
  try {
    const tabs = [];
    for (const [path, f] of openFiles) tabs.push({ path, name: f.name, pinned: pinnedTabs.has(path) });
    localStorage.setItem("michael-ide.session-mirror", JSON.stringify({ workspaceRoots: [...workspaceRoots], rootPath, activePath, tabs }));
  } catch { /* quota / disabled */ }
}

async function saveSession() {
  if (!inTauri || _isSecondaryWindow) return; // secondary windows never overwrite main's session
  // Capture the ACTIVE file's current cursor/scroll/folds now (it's only snapshotted
  // into f.viewState when you switch away, so without this the active tab loses it).
  try { const af = activePath && openFiles.get(activePath); if (af && af.model && monacoEditor) af.viewState = monacoEditor.saveViewState(); } catch {}
  const tabList = [];
  for (const [path, f] of openFiles) {
    tabList.push({ path, name: f.name, dirty: false, pinned: pinnedTabs.has(path), viewState: f.viewState || null });
  }
  const session = {
    workspaceRoots: [...workspaceRoots],
    rootPath,
    activePath,
    tabs: tabList,
  };
  try {
    const store = await loadStore("session.json");
    await store.set(SESSION_STORE_KEY, session);
    await store.save();
  } catch (e) {
    console.warn("[session] save failed:", e);
  }
  await saveChatHistory();
}

// Persist the session eagerly (debounced) whenever the workspace or active file
// changes — so the last project survives a crash / force-quit, not only a clean
// close (webview `beforeunload` is unreliable and the close-requested save races
// window destruction, which is why the last project was often forgotten).
let _sessionSaveTimer = 0;
function scheduleSaveSession() {
  clearTimeout(_sessionSaveTimer);
  _sessionSaveTimer = setTimeout(() => { saveSession().catch(() => {}); }, 600);
}

async function restoreSession() {
  if (!inTauri || _isSecondaryWindow) return; // secondary windows start fresh (open your own folder)
  try {
    const store = await loadStore("session.json");
    let session = await store.get(SESSION_STORE_KEY);
    // Fallback: a non-clean exit may have left only the synchronous localStorage mirror.
    if (!session) {
      try { const raw = localStorage.getItem("michael-ide.session-mirror"); if (raw) session = JSON.parse(raw); } catch {}
    }
    if (!session) {
      _requestWorkspaceFromPeers();
      return;
    }
    // Only keep real non-empty string paths — a stale/legacy/corrupt store could hold
    // null/object entries that crash basename() ("t.split is not a function") on render.
    if (Array.isArray(session.workspaceRoots)) session.workspaceRoots = session.workspaceRoots.filter((r) => typeof r === "string" && r);
    if (Array.isArray(session.workspaceRoots) && session.workspaceRoots.length) {
      workspaceRoots = session.workspaceRoots;
      for (const root of workspaceRoots) {
        try { await backend.registerWorkspaceRoot(root); } catch {}
      }
      setActiveWorkspaceRoot(session.rootPath || workspaceRoots[0]);
      await renderWorkspaceRoots();
      startFileWatcher();
      _idleRun(() => { _warmMcpTools(session.rootPath || workspaceRoots[0]); });
      await refreshGitStatus();
      // Sequential await: preloadProjectModels shares a module-level token + projectModels set and
      // clears them on entry — firing it concurrently for N roots orphans earlier roots' models
      // (their tracking gets wiped mid-walk, so they're never disposed). One at a time = no orphan.
      for (const root of workspaceRoots) await preloadProjectModels(root);
    } else {
      _requestWorkspaceFromPeers();
    }
    if (Array.isArray(session.tabs)) {
      for (const t of session.tabs) {
        // Restore models and tab metadata without switching the editor for every
        // tab. Activate exactly once below after all saved tabs are available.
        await openFile(t.path, t.name, false).catch(() => {});
        if (t.pinned) pinnedTabs.add(t.path);
        // Restore cursor/scroll/folds so reopening lands you where you left off.
        if (t.viewState) { const of = openFiles.get(t.path); if (of) of.viewState = t.viewState; }
      }
    }
    if (session.activePath && openFiles.has(session.activePath)) {
      activate(session.activePath); // applies that tab's restored viewState (see activate)
    } else if (openFiles.size) {
      activate([...openFiles.keys()].pop());
    }
    // Hot-exit recovery: re-apply unsaved buffer content a crash / reload / force-quit
    // left behind (beforeunload wrote it synchronously). Restores edits the 800ms
    // autosave hadn't flushed yet, re-marking those tabs dirty so they get saved.
    try {
      const raw = localStorage.getItem("michael-ide.unsaved-buffers");
      if (raw) {
        const list = JSON.parse(raw);
        let recovered = 0;
        for (const u of (Array.isArray(list) ? list : [])) {
          if (!u || !u.path || typeof u.content !== "string") continue;
          let f = openFiles.get(u.path);
          if (!f) { await openFile(u.path, u.path.split("/").pop()).catch(() => {}); f = openFiles.get(u.path); }
          if (f && f.model && f.model.getValue() !== u.content) {
            f.model.setValue(u.content);
            f.dirty = true;
            const tabEl = tabsEl.querySelector(`[data-path="${CSS.escape(u.path)}"]`);
            if (tabEl) tabEl.classList.add("dirty");
            recovered++;
          }
        }
        localStorage.removeItem("michael-ide.unsaved-buffers");
        if (recovered) showToast(`已恢复 ${recovered} 个未保存的改动`);
      }
    } catch {}
    updateStatusBar();
  } catch (e) {
    console.warn("[session] restore failed:", e);
    _requestWorkspaceFromPeers();
  }
}

function _requestWorkspaceFromPeers() {
  if (_ipcChannel) {
    _ipcChannel.postMessage({ type: "workspace_request", from: _WINDOW_ID });
  }
}

// ---- zen mode ----
let zenModeActive = false;
function toggleZenMode() {
  zenModeActive = !zenModeActive;
  document.body.classList.toggle("zen-mode", zenModeActive);
  const p = effectivePrefs();
  monacoEditor.updateOptions({
    lineNumbers: zenModeActive ? "off" : "on",
    glyphMargin: !zenModeActive,
    folding: !zenModeActive,
    minimap: { enabled: zenModeActive ? false : p.minimap !== false },
  });
  monacoEditor.layout();
}

// ---- drag & drop into the IDE, with TWO clearly-distinguished drop targets ----
// Dragging OS files/folders over the IDE lights up two zones so you can SEE where they'll land:
//   • the file-explorer sidebar → OPEN into the working directory (file → open, folder → workspace)
//   • the AI composer           → @-REFERENCE the file(s) as context in the chat
// The zone under the cursor is the ACTIVE target (bright + lifted badge); the other stays dimmed.
// Purely visual (pointer-events:none) — Tauri catches the real drop and we route it by drop position.
const _explorerEl = document.getElementById("explorer");
const _composerEl = document.getElementById("composer");
// Precise Lucide-geometry icons. folder-down = open into workspace; bot = reference in AI chat.
const _ICON_OPEN = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M20 20a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.9a2 2 0 0 1-1.69-.9L9.6 3.9A2 2 0 0 0 7.93 3H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2Z"/><path d="M12 10v6"/><path d="m9 13 3 3 3-3"/></svg>';
const _ICON_AI = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 8V4H8"/><rect width="16" height="12" x="4" y="8" rx="2"/><path d="M2 14h2"/><path d="M20 14h2"/><path d="M15 13v2"/><path d="M9 13v2"/></svg>';
function _mkDropZone(cls, labelCls, icon, label) {
  const z = document.createElement("div");
  z.className = cls;
  z.innerHTML = '<span class="dz-label ' + labelCls + '">' + icon + '<span>' + label + '</span></span>';
  return z;
}
if (_explorerEl) _explorerEl.appendChild(_mkDropZone("explorer-dropzone", "dz-label--open", _ICON_OPEN, "打开到工作区"));
if (_composerEl) _composerEl.appendChild(_mkDropZone("composer-dropzone", "dz-label--ai", _ICON_AI, "引用到对话"));

let _dropHideTimer = 0;
// Which target is the cursor over? Checks the composer rect against BOTH the raw position and the
// devicePixelRatio-divided one, so it works whether Tauri reports physical or logical px (and for the
// browser path where we pass client px). Anything not over the composer → "open" (sidebar/editor).
function _dragTargetAt(payload) {
  const p = payload && payload.position;
  if (p && _composerEl) {
    const r = _composerEl.getBoundingClientRect();
    if (r.width && r.height) {
      const dpr = window.devicePixelRatio || 1;
      const hit = (x, y) => x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
      if (hit(p.x / dpr, p.y / dpr) || hit(p.x, p.y)) return "composer";
    }
  }
  return "open";
}
function _showDrop(target) {
  clearTimeout(_dropHideTimer);
  const composer = target === "composer";
  if (_explorerEl) { _explorerEl.classList.add("drag-into"); _explorerEl.classList.toggle("is-over", !composer); }
  if (_composerEl) { _composerEl.classList.add("drag-into"); _composerEl.classList.toggle("is-over", composer); }
}
function _hideDrop() {
  clearTimeout(_dropHideTimer);
  for (const el of [_explorerEl, _composerEl]) { if (el) { el.classList.remove("drag-into"); el.classList.remove("is-over"); } }
}
// drag-leave can fire spuriously mid-drag; debounce the hide so the zones don't flicker.
const _hideDropSoon = () => { clearTimeout(_dropHideTimer); _dropHideTimer = setTimeout(_hideDrop, 130); };

// Reference an OS path in the composer: keep it workspace-relative when inside a root, else absolute
// so the @-mention reader can still resolve a file from outside the workspace.
function _pathToRefArg(abs) {
  const inWs = (workspaceRoots || []).some((w) => abs === w || abs.startsWith(w.replace(/\/$/, "") + "/"))
    || (rootPath && abs.startsWith(rootPath.replace(/\/$/, "") + "/"));
  return inWs ? _pathToRel(abs) : abs;
}
async function _handleDrop(paths, target) {
  if (!paths || !paths.length) return;
  if (target === "composer") {
    for (const p of paths) {
      const normalizedPath = _toPosix(p);
      const name = basename(normalizedPath);
      if (isImageFile(name) || isVideoFile(name)) {
        try {
          const attachment = await _mediaAttachmentFromPath(normalizedPath);
          _pastedImages.push(attachment);
          _refreshImagePreviews();
          showToast(`${attachment.kind === "video" ? "Video" : "Image"} attached: ${name}`);
        } catch (error) {
          showToast(String(error?.message || error));
        }
      } else {
        _insertRefAtCursor(_pathToRefArg(normalizedPath));
      }
    }
    try { promptEl.focus(); } catch {}
  } else {
    for (const p of paths) {
      const name = p.split("/").pop() || p;
      const isDir = await backend.readDir(p).then(() => true).catch(() => false);
      if (isDir) await openFolder(p);
      else await openFile(p, name);
    }
  }
}

// Browser / non-Tauri path (HTML5 DnD works there; it's swallowed under Tauri WKWebView).
editorContainer.addEventListener("dragover", (e) => {
  e.preventDefault();
  e.dataTransfer.dropEffect = "copy";
  _showDrop(_dragTargetAt({ position: { x: e.clientX, y: e.clientY } }));
});
editorContainer.addEventListener("dragleave", () => _hideDropSoon());
editorContainer.addEventListener("drop", async (e) => {
  e.preventDefault();
  const target = _dragTargetAt({ position: { x: e.clientX, y: e.clientY } });
  _hideDrop();
  const files = [...(e.dataTransfer?.files || [])].map((f) => f.path).filter(Boolean);
  await _handleDrop(files, target);
});
// Tauri path: window-level drag events drive the zones AND route the drop by position.
if (inTauri) {
  import("@tauri-apps/api/event").then(({ listen }) => {
    listen("tauri://drag-enter", (e) => _showDrop(_dragTargetAt(e.payload)));
    listen("tauri://drag-over", (e) => _showDrop(_dragTargetAt(e.payload)));
    listen("tauri://drag-leave", () => _hideDropSoon());
    listen("tauri://drag-drop", async (event) => {
      const target = _dragTargetAt(event.payload);
      _hideDrop();
      await _handleDrop(event.payload?.paths || [], target);
    });
  }).catch(() => {});
}

window.addEventListener("beforeunload", () => { _flushChatHistorySync(); _flushDirtyBuffersSync(); _flushSessionSync(); saveSession(); });
if (inTauri) {
  import("@tauri-apps/api/window").then(({ getCurrentWindow }) => {
    const currentWindow = getCurrentWindow();
    currentWindow.onCloseRequested(async (event) => {
      event.preventDefault();
      _flushChatHistorySync(); _flushDirtyBuffersSync(); _flushSessionSync();
      // Wake any debounced chat save and wait for the current in-flight write plus
      // its trailing snapshot before destroying the WebView.
      await Promise.all([saveChatHistory({ immediate: true }), saveSession()]);
      await currentWindow.destroy();
    });
  }).catch(() => {});
}
restoreSession().then(() => _loadBreakpoints()).catch(() => _loadBreakpoints());
// Restore the Michael login session (keeps the user logged in across restarts).
restoreMichaelSession();
// Keep the plan/credits live: re-fetch when the window regains focus (e.g. you just
// changed the plan in the backend admin and switched back) + a slow background poll.
// This is why an admin plan/credit change now shows up without restarting the IDE.
window.addEventListener("focus", () => refreshMichaelUser());
document.addEventListener("visibilitychange", () => { if (!document.hidden) refreshMichaelUser(); });
// Idempotent: clear any prior timer so a Vite HMR re-run can't stack duplicate
// pollers (stacked pollers = duplicate account-info refreshes / toast spam).
if (typeof window !== "undefined" && window.__michaelUserTimer) clearInterval(window.__michaelUserTimer);
{
  const _mut = setInterval(() => { if (!document.hidden) refreshMichaelUser(); }, 60000);
  if (typeof window !== "undefined") window.__michaelUserTimer = _mut;
}

